import type {
  OpenLyricFontFaceList,
  OpenLyricFontFaceSection,
} from './types.ts';

/**
 * Normalizes whatever a host assigned to `fontFaces` into the sectioned shape
 * the font-family picker renders.
 *
 * Hosts may hand over a flat list (`['Arial', 'Georgia']`), titled sections
 * (`[{ title: 'Serif', fontFaces: [...] }]`), or a mix. Bare strings
 * collapse into a single untitled section that keeps its position ahead of the
 * first titled one, so a flat list stays one plain group of entries. Blank
 * names and duplicates (across the whole list, first occurrence wins) are
 * dropped, and sections left with no entries disappear.
 */
export function normalizeFontFaceSections(
  list: OpenLyricFontFaceList | null | undefined,
): OpenLyricFontFaceSection[] {
  if (!Array.isArray(list)) {
    return [];
  }

  const sections: OpenLyricFontFaceSection[] = [];
  const seen = new Set<string>();
  let looseSection: OpenLyricFontFaceSection | null = null;

  const push = (target: OpenLyricFontFaceSection, face: unknown): void => {
    const value = String(face ?? '').trim();
    if (!value || seen.has(value)) {
      return;
    }
    seen.add(value);
    target.fontFaces.push(value);
  };

  for (const entry of list) {
    if (typeof entry === 'string') {
      // Bare names share one untitled section, wherever they appear.
      if (!looseSection) {
        looseSection = { title: '', fontFaces: [] };
        sections.push(looseSection);
      }
      push(looseSection, entry);
      continue;
    }
    if (!entry || typeof entry !== 'object') {
      continue;
    }
    const section: OpenLyricFontFaceSection = {
      title: String(entry.title ?? '').trim(),
      fontFaces: [],
    };
    for (const face of Array.isArray(entry.fontFaces) ? entry.fontFaces : []) {
      push(section, face);
    }
    sections.push(section);
  }

  return sections.filter((section) => section.fontFaces.length > 0);
}
