import { olEditorOpenLyricPluginData } from './open-lyric_ol_editor.ts';
import {
  MARKER_OWNER,
  VALIDATION_DELAY_MS,
} from '../../editor/scripts/shared.ts';
import type {
  OpenLyricComponentHost,
  OpenLyricContributions,
  OpenLyricPlugin,
  OpenLyricSurface,
} from '../../editor/components/index.ts';

/**
 * The Open Lyric notation plugin expressed in the generic per-component
 * contract from `research/editor-structure-enhanced.md`. All contribution
 * data is the real registry data (`open-lyric_ol_editor.ts`) — the same
 * parser/validation/preview APIs and example documents the application
 * consumes — not a parallel copy.
 *
 * On a standalone `Editor` the plugin is live: it runs the real markdown-ol
 * validation against the editor's Monaco model (debounced like the
 * application) so squiggles/markers work outside the app shell. The language
 * itself is registered by the component Monaco boot; the singleton
 * `notation` kind means a component rejects a second notation plugin.
 *
 * On the app pages the wrapped application provides the notation features
 * through the legacy shell registry, so there the class is the page's
 * composition manifest (`open-lyric.html` attaches it; `editor.html` does
 * not) — see `OpenLyricDashboard`.
 *
 * Shared-state note: `validateMarkdownOlModel` also updates the page-wide
 * error count (`shared.ts` state), which de-globalizes in a later phase.
 */

/** Duck-typed view of `Editor` the validator needs. */
interface MonacoEditorHostLike {
  monacoEditor?: { getModel?: () => unknown } | null;
  monacoNamespace?: unknown;
}

interface MonacoModelLike {
  getLinesContent(): string[];
  uri: unknown;
}

const openLyricValidation =
  olEditorOpenLyricPluginData.openLyric.document.validation;

class EditorOpenLyricPlugin implements OpenLyricPlugin {
  readonly id = 'open-lyric';
  readonly apiVersion = 1 as const;
  readonly surfaces: readonly OpenLyricSurface[] = ['editor', 'dashboard'];
  readonly contributes: OpenLyricContributions = {
    // Singleton kind: a component rejects a second notation plugin.
    notation: {
      id: olEditorOpenLyricPluginData.id,
      exampleGroupTitle: olEditorOpenLyricPluginData.exampleGroupTitle,
      examples: olEditorOpenLyricPluginData.examples,
      openLyric: olEditorOpenLyricPluginData.openLyric,
    },
  };

  private validationTimer: number | null = null;

  install(): void {}

  uninstall(): void {
    this.clearValidationTimer();
  }

  onMount(host: OpenLyricComponentHost): void {
    this.validateNow(host);
  }

  onUnmount(host: OpenLyricComponentHost): void {
    this.clearValidationTimer();
    // Leave the model clean for the next language/plugin configuration.
    const model = this.resolveModel(host);
    if (model) {
      (globalThis as { monaco?: any }).monaco?.editor?.setModelMarkers(
        model,
        MARKER_OWNER,
        [],
      );
    }
  }

  onValueChange(host: OpenLyricComponentHost): void {
    this.clearValidationTimer();
    this.validationTimer = window.setTimeout(() => {
      this.validationTimer = null;
      this.validateNow(host);
    }, VALIDATION_DELAY_MS);
  }

  /** The real notation API (parser, validation, preview, music theory). */
  getOpenLyricApi() {
    return olEditorOpenLyricPluginData.openLyric;
  }

  /** The bundled example documents (same set the app's Reset dialog shows). */
  getExamples() {
    return olEditorOpenLyricPluginData.examples;
  }

  private validateNow(host: OpenLyricComponentHost): void {
    const model = this.resolveModel(host);
    if (model) {
      openLyricValidation.validateMarkdownOlModel(model);
    }
  }

  private resolveModel(host: OpenLyricComponentHost): MonacoModelLike | null {
    const editorHost = host as unknown as MonacoEditorHostLike;
    const model = editorHost.monacoEditor?.getModel?.();
    return (model as MonacoModelLike) ?? null;
  }

  private clearValidationTimer(): void {
    if (this.validationTimer !== null) {
      window.clearTimeout(this.validationTimer);
      this.validationTimer = null;
    }
  }
}

export { EditorOpenLyricPlugin };
