import editorActionsHtml from './editor-actions.html?raw';
import panelHtml from './panel.html?raw';
import previewSettingsFieldsHtml from './preview-settings-fields.html?raw';
import topbarToggleHtml from './topbar-toggle.html?raw';
import {
  ensureScopeClass,
  OPEN_LYRIC_SCOPE_CLASS,
  replaceMountWithFragment,
} from '../../../editor/html/markup-fragments.ts';

function installOpenLyricShellMarkup() {
  replaceMountWithFragment('builtInPluginPanel', 'openLyricPanel', panelHtml);
  ensureScopeClass('openLyricPanel', OPEN_LYRIC_SCOPE_CLASS.lyric);
  replaceMountWithFragment(
    'builtInPluginTopbarToggle',
    'toggleOpenLyricBtn',
    topbarToggleHtml,
  );
  replaceMountWithFragment(
    'openLyricPreviewSettings',
    'openLyricPluginToggle',
    previewSettingsFieldsHtml,
  );
  // The chord-bars action inside the shared editor panel (installed by
  // `Editor.installShellMarkup()` first — its mount lives in that panel).
  replaceMountWithFragment(
    'openLyricEditorActions',
    'toggleChordBarsBtn',
    editorActionsHtml,
  );
}

export { installOpenLyricShellMarkup };
