import {
  DARK_LANGUAGE_THEME,
  LANGUAGE_THEME,
  refs,
  runtime,
  state,
} from '../shared.ts';
import { defineOpenLyricMonacoThemes } from '../monaco-theme.ts';
import { hideChordDiagramPopup } from '../../../plugins/OpenLyric/chord-popup.ts';

const SYSTEM_DARK_THEME_MEDIA_QUERY = '(prefers-color-scheme: dark)';

/**
 * Keeps theme state and UI synchronized while exposing a small surface to the
 * composition root.
 */
class ThemeController {
  constructor({ monaco, preferences, onThemeApplied = null }) {
    this.monaco = monaco;
    this.preferences = preferences;
    this.onThemeApplied = onThemeApplied;
    this.systemThemeMediaQuery = null;
    this.systemThemeListenerBound = false;
    this.handleSystemThemeChange = this.handleSystemThemeChange.bind(this);
  }

  setMonaco(monaco) {
    this.monaco = monaco;
    this.ensureEditorThemesRegistered();
  }

  ensureEditorThemesRegistered() {
    if (!this.monaco?.editor || runtime.languageRegistered) {
      return;
    }

    defineOpenLyricMonacoThemes(this.monaco.editor);
  }

  getEditorTheme(theme = state.theme) {
    return theme === 'dark' ? DARK_LANGUAGE_THEME : LANGUAGE_THEME;
  }

  getSystemThemeMediaQuery() {
    if (this.systemThemeMediaQuery) {
      return this.systemThemeMediaQuery;
    }

    if (typeof globalThis.matchMedia !== 'function') {
      return null;
    }

    try {
      this.systemThemeMediaQuery = globalThis.matchMedia(
        SYSTEM_DARK_THEME_MEDIA_QUERY,
      );
    } catch (_error) {
      return null;
    }

    return this.systemThemeMediaQuery;
  }

  getSystemThemePreference() {
    const systemThemeMediaQuery = this.getSystemThemeMediaQuery();

    if (typeof systemThemeMediaQuery?.matches === 'boolean') {
      return systemThemeMediaQuery.matches ? 'dark' : 'light';
    }

    return this.preferences.loadThemePreference();
  }

  bindSystemThemeListener() {
    if (this.systemThemeListenerBound) {
      return;
    }

    const systemThemeMediaQuery = this.getSystemThemeMediaQuery();

    if (!systemThemeMediaQuery) {
      return;
    }

    if (typeof systemThemeMediaQuery.addEventListener === 'function') {
      systemThemeMediaQuery.addEventListener(
        'change',
        this.handleSystemThemeChange,
      );
      this.systemThemeListenerBound = true;
      return;
    }

    if (typeof systemThemeMediaQuery.addListener === 'function') {
      systemThemeMediaQuery.addListener(this.handleSystemThemeChange);
      this.systemThemeListenerBound = true;
    }
  }

  handleSystemThemeChange() {
    if (this.preferences.hasStoredThemePreference()) {
      return;
    }

    this.applyTheme(this.getSystemThemePreference());
  }

  applyPreferredTheme() {
    const storedTheme = this.preferences.loadStoredThemePreference();

    this.bindSystemThemeListener();
    this.applyTheme(storedTheme ?? this.getSystemThemePreference(), {
      notifyThemeApplied: false,
    });
  }

  bindEvents() {
    refs.themeToggleBtn?.addEventListener('click', () => {
      this.toggleTheme();
    });
  }

  applyTheme(theme, { notifyThemeApplied = true } = {}) {
    const nextTheme = this.preferences.normalizeTheme(theme);
    const isDarkTheme = nextTheme === 'dark';
    const themeToggleLabel = isDarkTheme
      ? 'Switch to light mode'
      : 'Switch to dark mode';

    state.theme = nextTheme;
    document.documentElement.dataset.theme = nextTheme;
    document.documentElement.setAttribute('data-bs-theme', nextTheme);
    hideChordDiagramPopup();

    if (refs.themeToggleBtn) {
      refs.themeToggleBtn.setAttribute('aria-pressed', String(isDarkTheme));
      refs.themeToggleBtn.setAttribute('aria-label', themeToggleLabel);
      refs.themeToggleBtn.setAttribute('title', themeToggleLabel);
      refs.themeToggleBtn.querySelector(
        '[data-theme-toggle-label]',
      ).textContent = themeToggleLabel;
    }

    this.ensureEditorThemesRegistered();

    if (this.monaco?.editor) {
      this.monaco.editor.setTheme(this.getEditorTheme(nextTheme));
    }

    if (notifyThemeApplied) {
      this.onThemeApplied?.(nextTheme);
    }
  }

  setTheme(theme) {
    const nextTheme = this.preferences.normalizeTheme(theme);
    this.applyTheme(nextTheme);
    this.preferences.saveThemePreference(nextTheme);
  }

  toggleTheme() {
    this.setTheme(state.theme === 'dark' ? 'light' : 'dark');
  }
}

export { ThemeController };
