import { OpenLyricComponent } from './OpenLyricComponent.ts';
import { normalizeFontFaceSections } from './font-faces.ts';
import { normalizeFontSize } from './font-size.ts';
import { ensureFontFacesInjected } from './font-styles.ts';
import { ensureThemeVarsInjected } from './theme-vars-styles.ts';
import {
  type OpenLyricEditorLike,
  type OpenLyricFontFaceList,
  type OpenLyricFontFaceSection,
  type OpenLyricLanguageContribution,
  type OpenLyricPreviewOptions,
  type OpenLyricTheme,
  type Unsubscribe,
} from './types.ts';

/** Renderer targets shared by both preview surfaces. */
const SECTION_RENDERER_SELECTORS: Record<string, string> = {
  lyric: '.ol-song-view__section',
  markdown: '.ol-preview-segment',
};

/**
 * Shared base for the two read-only previews (`OpenLyric`, the lyric preview,
 * and `OpenLyricMarkdownManager`, the markdown preview).
 *
 * Adds to {@link OpenLyricComponent}:
 * - a `value` setter + render pipeline backed by a subclass `renderMarkup()`
 * - the editor **bridge** (`editor` / `isWeakRef`): one-way value+theme mirror,
 *   double-click → `focusRange`, and destroy-driven ref cleanup
 * - settable typography exposed as `--ol-*` custom properties
 *
 * Both previews are Monaco-free and fully standalone; attaching an editor is
 * optional and never required to render.
 */
export abstract class OpenLyricPreviewComponent extends OpenLyricComponent {
  /**
   * Host-supplied options merged over this component's own render options on
   * every render (host keys win). Lets an embedding shell thread renderer
   * context (e.g. pattern-preview targets, per-structure keys) through the
   * component without subclassing.
   */
  extraRenderOptions: Record<string, unknown> | null = null;

  private valueText = '';
  private renderRoot: HTMLElement | null = null;
  private adoptContainerValue = false;

  private editorRef: OpenLyricEditorLike | null = null;
  private weakRef = true;
  private readonly editorBridgeUnsubscribes: Unsubscribe[] = [];

  private fontFamilyValue = '';
  private fontSizeValue = '';
  private fontFacesValue: OpenLyricFontFaceList = [];

  private readonly boundDoubleClick = (event: MouseEvent) =>
    this.handleDoubleClick(event);

  constructor(options: OpenLyricPreviewOptions = {}) {
    super(options);
    if (typeof options.value === 'string') {
      this.valueText = options.value;
    }
    if (options.fontFamily) {
      this.fontFamilyValue = options.fontFamily;
    }
    if (options.fontSize) {
      this.fontSizeValue = options.fontSize;
    }
    if (Array.isArray(options.fontFaces)) {
      this.fontFacesValue = options.fontFaces.slice();
    }
    this.adoptContainerValue = options.adoptContainer === true;
  }

  /** See {@link OpenLyricPreviewOptions.adoptContainer}. */
  get adoptContainer(): boolean {
    return this.adoptContainerValue;
  }

  set adoptContainer(next: boolean) {
    if (this.isMounted) {
      throw new Error('adoptContainer cannot change while mounted.');
    }
    this.adoptContainerValue = Boolean(next);
  }

  /* ------------------------------- value --------------------------------- */

  get value(): string {
    return this.editorRef ? this.editorRef.getValue() : this.valueText;
  }

  set value(next: string) {
    this.assertNotDestroyed();
    // With an editor attached the editor is authoritative: the setter is a
    // no-op (the redesign's one-way mirror rule).
    if (this.editorRef) {
      return;
    }
    this.applyValue(String(next ?? ''));
  }

  /* --------------------------- editor bridge ----------------------------- */

  get editor(): OpenLyricEditorLike | null {
    return this.editorRef;
  }

  set editor(next: OpenLyricEditorLike | null) {
    if (next === this.editorRef) {
      return;
    }

    // Assigning a new (or null) editor first detaches the previous bridge.
    this.detachEditorBridge();

    if (!next) {
      this.editorRef = null;
      // A standalone preview keeps whatever value it last mirrored.
      return;
    }

    this.editorRef = next;
    this.attachEditorBridge(next);
  }

  get isWeakRef(): boolean {
    return this.weakRef;
  }

  set isWeakRef(next: boolean) {
    this.weakRef = Boolean(next);
  }

  /* ----------------------------- typography ------------------------------ */

  /**
   * The font faces offered for picking. Round-trips whatever shape the host
   * assigned — a flat list of names, titled sections, or a mix; use
   * {@link getFontFaceSections} for the normalized sectioned view.
   */
  get fontFaces(): OpenLyricFontFaceList {
    return this.fontFacesValue.slice();
  }

  set fontFaces(next: OpenLyricFontFaceList) {
    this.fontFacesValue = Array.isArray(next) ? next.slice() : [];
  }

  /**
   * `fontFaces` normalized into titled sections — what the standalone chrome's
   * font-family picker lists. Bare names collapse into one untitled section;
   * blanks, duplicates, and empty sections drop out.
   *
   * Attached plugins' `language.fontFaces` are appended after the host's own
   * list, the preview counterpart of {@link Editor.resolvedFontFamily}: a
   * language plugin ships its faces that way, so composing it is all an embed
   * needs for them to appear in the picker — no page has to name a face
   * itself. A host that sets `fontFaces` still leads the list; assigning it
   * no longer hides what the plugins contribute.
   */
  getFontFaceSections(): OpenLyricFontFaceSection[] {
    const pluginFaces = this.pluginContributions<
      OpenLyricLanguageContribution | undefined
    >('language').flatMap((language) => language?.fontFaces ?? []);

    return normalizeFontFaceSections([...this.fontFacesValue, ...pluginFaces]);
  }

  get fontFamily(): string {
    return this.fontFamilyValue;
  }

  set fontFamily(next: string) {
    const value = String(next ?? '');
    const changed = value !== this.fontFamilyValue;
    this.fontFamilyValue = value;
    this.applyTypography();
    if (changed) {
      this.emitTypographyChange();
    }
  }

  get fontSize(): string {
    return this.fontSizeValue;
  }

  set fontSize(next: string) {
    const value = normalizeFontSize(next);
    const changed = value !== this.fontSizeValue;
    this.fontSizeValue = value;
    this.applyTypography();
    if (changed) {
      this.emitTypographyChange();
    }
  }

  /**
   * Announce a typography change so host UI (and the standalone chrome's
   * settings controls) can mirror a programmatic `fontSize`/`fontFamily` set,
   * the same way `theme-change` lets listeners follow `theme`.
   */
  private emitTypographyChange(): void {
    this.emitter.emit('typography-change', {
      fontSize: this.fontSizeValue,
      fontFamily: this.fontFamilyValue,
    });
  }

  /* ---------------------- subclass render contract ----------------------- */

  /** The scoped root class (e.g. `ol-lyric-preview`). */
  protected abstract rootClassName(): string;

  /** Render the current value to an HTML string using the subclass backing. */
  protected abstract renderMarkup(
    value: string,
    options: Record<string, unknown>,
  ): string;

  /** Options bag passed to `renderMarkup` (chord/key toggles, etc.). */
  protected getRenderOptions(): Record<string, unknown> {
    return {};
  }

  /** The mounted render root, so concrete getters can query rendered DOM. */
  protected getRenderRoot(): HTMLElement | null {
    return this.renderRoot;
  }

  protected override getOwnedRoot(): HTMLElement | null {
    // Adopt mode: the root is the host's element — never restyle it.
    return this.adoptContainerValue ? null : this.renderRoot;
  }

  protected override getPluginStyleHost(): HTMLElement | null {
    // Adopt mode: the container is host-owned content — its innerHTML is
    // replaced every render and hosts inspect its emptiness (export
    // availability), so plugin styles must not live inside it. Park them in
    // <head>, tagged with the plugin id (the legacy registry's pattern);
    // they are still removed on detach/unmount/destroy.
    if (this.adoptContainer) {
      return this.container?.ownerDocument?.head ?? null;
    }
    return super.getPluginStyleHost();
  }

  /** Render the current value to a detached string (used by getters). */
  protected renderCurrentHtml(): string {
    try {
      return this.renderMarkup(this.value, {
        ...this.getRenderOptions(),
        ...(this.extraRenderOptions || {}),
      });
    } catch (error) {
      console.error('Open Lyric preview render failed.', error);
      return '';
    }
  }

  /**
   * Re-render into the mounted root; safe to call any time. Each pass fires
   * the plugin render hooks (`onBeforeRender` → render → `onAfterRender`) and
   * re-applies `renderers` contributions on the fresh markup.
   */
  protected renderNow(): void {
    const root = this.renderRoot;
    if (!root) {
      return;
    }
    const context = { value: this.value, root };
    this.pluginHost.handleBeforeRender(context);
    root.innerHTML = this.renderCurrentHtml();
    if (!this.adoptContainerValue) {
      // Adopt mode defers all visuals to the host page's own stylesheet.
      this.decorateRenderedDom(root);
    }
    this.pluginHost.handleAfterRender(context);
  }

  /** Style freshly rendered markup from `--ol-*` variables (theme-aware). */
  protected decorateRenderedDom(_root: HTMLElement): void {}

  protected override handlePluginRenderRequest(): void {
    this.renderNow();
  }

  protected override resolveRendererTarget(target: string) {
    if (target === 'section') {
      const selector = SECTION_RENDERER_SELECTORS[this.surface];
      if (selector) {
        return {
          selector,
          getText: (element: Element) => element.textContent ?? '',
        };
      }
    }
    return null;
  }

  /* ------------------------------ lifecycle ------------------------------ */

  protected override handleMount(container: HTMLElement): void {
    let root: HTMLElement;
    if (this.adoptContainerValue) {
      root = container;
      root.classList.add('ol-preview-root', ...this.rootClassNames());
    } else {
      // A standalone embed loads no app stylesheet; supply the base theme
      // tokens the injected preview styles + chord popup reference, and the
      // app-shipped Latin `@font-face` declarations its print/export windows
      // link too (adopt-mode embeds inherit both from the host page instead —
      // its theme.scss and whatever surface shipped the faces there).
      ensureThemeVarsInjected();
      ensureFontFacesInjected();
      root = document.createElement('article');
      root.className = `ol-preview-root ${this.rootClassName()}`;
      container.append(root);
    }
    this.renderRoot = root;

    root.addEventListener('dblclick', this.boundDoubleClick);

    // Mirror the editor's current value on (re)mount if one is attached.
    if (this.editorRef) {
      this.valueText = this.editorRef.getValue();
    }
    this.applyTypography();
    this.renderNow();
  }

  protected override handleUnmount(): void {
    const root = this.renderRoot;
    if (!root) {
      return;
    }
    root.removeEventListener('dblclick', this.boundDoubleClick);
    if (this.adoptContainerValue) {
      // The element belongs to the host: empty it, drop our classes.
      root.replaceChildren();
      root.classList.remove('ol-preview-root', ...this.rootClassNames());
    } else {
      root.remove();
    }
    this.renderRoot = null;
  }

  private rootClassNames(): string[] {
    return this.rootClassName().split(/\s+/u).filter(Boolean);
  }

  protected override handleReload(): void {
    this.renderNow();
  }

  protected override handleDestroy(): void {
    const ownedEditor = !this.weakRef && this.editorRef ? this.editorRef : null;
    // Detach the bridge first so the owned editor's `destroy` event does not
    // re-enter and so listeners are gone before we tear anything down.
    this.detachEditorBridge();
    this.editorRef = null;
    ownedEditor?.destroy();
  }

  /* ------------------------------ internals ------------------------------ */

  private applyValue(next: string): void {
    const oldValue = this.valueText;
    if (next === oldValue) {
      return;
    }
    this.valueText = next;
    this.renderNow();
    this.pluginHost.handleValueChange(oldValue, next);
    this.emitter.emit('change', { oldValue, newValue: next });
  }

  private applyTypography(): void {
    const root = this.renderRoot;
    if (!root) {
      return;
    }
    // The root always consumes `font-*: var(--ol-font-*, inherit)` (see
    // applyThemeSurfaceStyles); the setters only provide the variable, so a
    // host can also drive both from any ancestor.
    if (this.fontFamilyValue) {
      root.style.setProperty('--ol-font-family', this.fontFamilyValue);
    } else {
      root.style.removeProperty('--ol-font-family');
    }
    if (this.fontSizeValue) {
      root.style.setProperty('--ol-font-size', this.fontSizeValue);
    } else {
      root.style.removeProperty('--ol-font-size');
    }
  }

  private attachEditorBridge(editor: OpenLyricEditorLike): void {
    // Bridge value: the editor drives the preview one way.
    this.editorBridgeUnsubscribes.push(
      editor.on('change', ({ newValue }) => {
        const oldValue = this.valueText;
        if (newValue === oldValue) {
          return;
        }
        this.valueText = newValue;
        this.renderNow();
        this.pluginHost.handleValueChange(oldValue, newValue);
        this.emitter.emit('change', { oldValue, newValue });
      }),
    );

    // When the editor is destroyed, drop the reference (idempotent cleanup).
    this.editorBridgeUnsubscribes.push(
      editor.on('destroy', () => {
        this.editor = null;
      }),
    );

    // Initial sync: adopt the editor's value and push our theme onto it.
    this.valueText = editor.getValue();
    try {
      editor.theme = this.theme;
    } catch {
      // Editors that expose theme read-only can ignore this.
    }
    this.renderNow();
  }

  private detachEditorBridge(): void {
    while (this.editorBridgeUnsubscribes.length) {
      const off = this.editorBridgeUnsubscribes.pop();
      off?.();
    }
  }

  protected override handleThemeChange(theme: OpenLyricTheme): void {
    // Keep an attached editor visually consistent with the preview.
    if (this.editorRef) {
      try {
        this.editorRef.theme = theme;
      } catch {
        // ignore read-only theme
      }
    }
    // Re-render so theme-preset decorations (chord/accent fallbacks) update.
    this.renderNow();
  }

  private handleDoubleClick(event: MouseEvent): void {
    const root = this.renderRoot;
    if (!root) {
      return;
    }

    const sourceElement = this.resolveSourceElement(event, root);
    if (!sourceElement) {
      return;
    }

    const line = Number(sourceElement.getAttribute('data-editor-line'));
    if (!Number.isFinite(line) || line < 1) {
      return;
    }
    const column =
      Number(sourceElement.getAttribute('data-editor-column')) || 1;
    const partName =
      sourceElement
        .closest('[data-ol-part-name]')
        ?.getAttribute('data-ol-part-name') ?? '';

    event.preventDefault();
    // Fires whether or not an editor is attached, so a host can react itself.
    this.emitter.emit('part-dblclick', { line, column, partName });
    this.editorRef?.focusRange(line, column);
  }

  /** Nearest rendered block carrying a source anchor to the pointer. */
  private resolveSourceElement(
    event: MouseEvent,
    root: HTMLElement,
  ): Element | null {
    const target = event.target instanceof Element ? event.target : null;
    const direct = target?.closest('[data-editor-line]:not(.ol-preview-fence)');
    if (direct && root.contains(direct)) {
      return direct;
    }

    const candidates = Array.from(
      root.querySelectorAll('[data-editor-line]'),
    ).filter((element) => !element.classList.contains('ol-preview-fence'));
    if (!candidates.length) {
      return null;
    }

    let nearest: Element | null = null;
    let nearestDistance = Number.POSITIVE_INFINITY;
    for (const element of candidates) {
      const rect = element.getBoundingClientRect();
      const dx =
        event.clientX < rect.left
          ? rect.left - event.clientX
          : event.clientX > rect.right
            ? event.clientX - rect.right
            : 0;
      const dy =
        event.clientY < rect.top
          ? rect.top - event.clientY
          : event.clientY > rect.bottom
            ? event.clientY - rect.bottom
            : 0;
      const distance = dx * dx + dy * dy;
      if (distance < nearestDistance) {
        nearestDistance = distance;
        nearest = element;
      }
    }
    return nearest;
  }
}
