import { refs, state, supportsClipboardCopy } from '../../shared.ts';
import {
  SHARE_COPY_BUTTON_LABELS,
  SHARE_COPY_BUTTON_RESET_DELAY_MS,
  SHARE_LINK_REFRESH_DELAY_MS,
  SHARE_QR_TEXT_DEFAULT_CHARACTERS_PER_CHUNK,
  SHARED_MARKDOWN_PASSWORD_DIALOG_MESSAGE,
  SHARED_MARKDOWN_PASSWORD_REQUIRED_MESSAGE,
  normalizeShareQrTextChunkLength,
} from './constants.ts';

function applyDocumentControllerShareUiMethods(DocumentControllerClass) {
  Object.assign(DocumentControllerClass.prototype, {
    handleShareDialogClose(this: any) {
      this.closeShareLinkQrFullscreen();
      this.prepareShareDialogState();
      state.editor?.focus();
    },

    clearShareCopyButtonResetTimer(this: any) {
      if (!this.shareCopyButtonResetTimer) {
        return;
      }

      globalThis.clearTimeout(this.shareCopyButtonResetTimer);
      this.shareCopyButtonResetTimer = 0;
    },

    clearShareLinkRefreshTimer(this: any) {
      if (!this.shareLinkRefreshTimer) {
        return;
      }

      globalThis.clearTimeout(this.shareLinkRefreshTimer);
      this.shareLinkRefreshTimer = 0;
    },

    syncShareCopyButtonVisibility(this: any) {
      if (!refs.copyShareLinkBtn) {
        return;
      }

      refs.copyShareLinkBtn.hidden =
        this.isShareQrModeSelected() || !supportsClipboardCopy();
    },

    setShareCopyButtonState(this: any, copyState, { disabled } = {}) {
      if (!refs.copyShareLinkBtn) {
        return;
      }

      const isQrMode = this.isShareQrModeSelected();
      const clipboardCopySupported = supportsClipboardCopy();

      refs.copyShareLinkBtn.dataset.copyState = copyState;
      refs.copyShareLinkBtn.textContent =
        SHARE_COPY_BUTTON_LABELS[copyState] || SHARE_COPY_BUTTON_LABELS.idle;
      this.syncShareCopyButtonVisibility();
      refs.copyShareLinkBtn.disabled =
        !clipboardCopySupported ||
        isQrMode ||
        (disabled ?? copyState === 'copying');
    },

    scheduleShareCopyButtonReset(this: any) {
      this.clearShareCopyButtonResetTimer();
      this.shareCopyButtonResetTimer = globalThis.setTimeout(() => {
        this.setShareCopyButtonState('idle');
        this.shareCopyButtonResetTimer = 0;
      }, SHARE_COPY_BUTTON_RESET_DELAY_MS);
    },

    scheduleShareLinkRefresh(this: any) {
      if (!refs.shareLinkDialog?.open) {
        return;
      }

      this.clearShareLinkRefreshTimer();
      this.shareLinkRefreshTimer = globalThis.setTimeout(() => {
        this.shareLinkRefreshTimer = 0;
        void this.refreshShareLink();
      }, SHARE_LINK_REFRESH_DELAY_MS);
    },

    ensureSharedLinkPasswordDialogBindings(this: any) {
      if (this.sharedLinkPasswordEventsBound) {
        return;
      }

      refs.sharedLinkPasswordForm?.addEventListener(
        'submit',
        this.handleSharedLinkPasswordSubmit,
      );
      refs.cancelSharedLinkPasswordBtn?.addEventListener(
        'click',
        this.handleSharedLinkPasswordCancel,
      );
      refs.sharedLinkPasswordDialog?.addEventListener(
        'close',
        this.handleSharedLinkPasswordDialogClose,
      );
      this.sharedLinkPasswordEventsBound = true;
    },

    setShareLinkMessage(this: any, message, tone = 'muted') {
      if (!refs.shareLinkMessage) {
        return;
      }

      refs.shareLinkMessage.dataset.tone = tone;
      refs.shareLinkMessage.textContent = message;
    },

    setSharedLinkPasswordMessage(this: any, message, tone = 'muted') {
      if (!refs.sharedLinkPasswordMessage) {
        return;
      }

      refs.sharedLinkPasswordMessage.dataset.tone = tone;
      refs.sharedLinkPasswordMessage.textContent = message;
    },

    updateShareEncryptionFieldsVisibility(this: any) {
      if (!refs.shareLinkEncryptionFields) {
        return;
      }

      refs.shareLinkEncryptionFields.hidden =
        !refs.shareLinkEncryptionToggle?.checked;
    },

    updateShareQrTextChunkFieldsVisibility(this: any) {
      if (!refs.shareLinkQrTextChunkFields) {
        return;
      }

      refs.shareLinkQrTextChunkFields.hidden =
        this.getShareOutputMode() !== 'qr-text';
    },

    getShareQrTextChunkLength(this: any) {
      return normalizeShareQrTextChunkLength(
        refs.shareLinkQrTextChunkLengthInput?.value,
      );
    },

    getShareOutputMode(this: any) {
      if (refs.shareLinkModeQrTextInput?.checked) {
        return 'qr-text';
      }

      if (refs.shareLinkModeQrLinkInput?.checked) {
        return 'qr-link';
      }

      return 'link';
    },

    isShareQrModeSelected(this: any) {
      return this.getShareOutputMode() !== 'link';
    },

    updateShareOutputModeVisibility(this: any) {
      const isQrMode = this.isShareQrModeSelected();

      this.updateShareQrTextChunkFieldsVisibility();

      if (refs.shareLinkTextarea) {
        refs.shareLinkTextarea.hidden = isQrMode;
      }

      if (refs.shareLinkQrPanel) {
        refs.shareLinkQrPanel.hidden = !isQrMode;
      }

      this.syncShareCopyButtonVisibility();
    },

    handleShareOutputModeChange(this: any) {
      this.shareQrPreviewTrigger = null;
      this.clearShareCopyButtonResetTimer();
      this.updateShareOutputModeVisibility();
      this.setShareCopyButtonState('idle', {
        disabled: !refs.shareLinkTextarea?.value,
      });

      if (this.isShareQrModeSelected()) {
        void this.refreshShareLinkQrFromCurrentValue();
        return;
      }

      this.focusAndSelectShareLink({ selectText: false });
    },

    focusDocumentElement(
      this: any,
      element,
      { preventScroll = true, skipTouchIosForButtons = false } = {},
    ) {
      if (typeof this.previewController?.focusElement === 'function') {
        this.previewController.focusElement(element, {
          preventScroll,
          skipTouchIosForButtons,
        });
        return;
      }

      if (
        !(element instanceof HTMLElement) ||
        typeof element.focus !== 'function'
      ) {
        return;
      }

      try {
        if (preventScroll) {
          element.focus({ preventScroll: true });
          return;
        }

        element.focus();
      } catch (_error) {
        element.focus();
      }
    },

    handleShareQrTextChunkLengthChange(this: any) {
      if (refs.shareLinkQrTextChunkLengthInput) {
        refs.shareLinkQrTextChunkLengthInput.value = String(
          this.getShareQrTextChunkLength(),
        );
      }

      if (this.getShareOutputMode() === 'qr-text') {
        this.shareQrPreviewTrigger = null;
        void this.refreshShareLinkQrFromCurrentValue();
      }
    },

    focusAndSelectShareLink(this: any, { selectText = true } = {}) {
      if (!refs.shareLinkTextarea || refs.shareLinkTextarea.hidden) {
        return;
      }

      this.focusDocumentElement(refs.shareLinkTextarea, {
        preventScroll: true,
      });

      if (selectText && refs.shareLinkTextarea.value) {
        refs.shareLinkTextarea.select();
      }
    },

    closeSharedLinkPasswordDialog(this: any, password = null) {
      this.sharedLinkPasswordValue = password;

      if (!refs.sharedLinkPasswordDialog?.open) {
        return;
      }

      refs.sharedLinkPasswordDialog.close(
        password === null ? 'cancel' : 'submit',
      );
    },

    handleSharedLinkPasswordCancel(this: any) {
      this.closeSharedLinkPasswordDialog(null);
    },

    handleSharedLinkPasswordDialogClose(this: any) {
      const resolver = this.sharedLinkPasswordResolver;

      if (refs.sharedLinkPasswordInput) {
        refs.sharedLinkPasswordInput.value = '';
      }

      this.setSharedLinkPasswordMessage(
        SHARED_MARKDOWN_PASSWORD_DIALOG_MESSAGE,
      );

      this.sharedLinkPasswordResolver = null;
      const password = this.sharedLinkPasswordValue;
      this.sharedLinkPasswordValue = null;

      if (resolver) {
        resolver(password);
      }
    },

    handleSharedLinkPasswordSubmit(this: any, event) {
      event.preventDefault();

      const password = String(refs.sharedLinkPasswordInput?.value || '');

      if (!password.length) {
        this.setSharedLinkPasswordMessage(
          SHARED_MARKDOWN_PASSWORD_REQUIRED_MESSAGE,
          'error',
        );
        this.focusDocumentElement(refs.sharedLinkPasswordInput, {
          preventScroll: true,
        });
        return;
      }

      this.closeSharedLinkPasswordDialog(password);
    },

    requestSharedLinkPassword(
      this: any,
      {
        message = SHARED_MARKDOWN_PASSWORD_DIALOG_MESSAGE,
        tone = 'muted',
      } = {},
    ) {
      if (!refs.sharedLinkPasswordDialog || !refs.sharedLinkPasswordInput) {
        return Promise.resolve(null);
      }

      if (this.sharedLinkPasswordResolver) {
        this.sharedLinkPasswordResolver(null);
        this.sharedLinkPasswordResolver = null;
      }

      this.sharedLinkPasswordValue = null;
      refs.sharedLinkPasswordInput.value = '';
      this.setSharedLinkPasswordMessage(message, tone);

      if (!refs.sharedLinkPasswordDialog.open) {
        refs.sharedLinkPasswordDialog.showModal();
      }

      this.focusDocumentElement(refs.sharedLinkPasswordInput, {
        preventScroll: true,
      });

      return new Promise((resolve) => {
        this.sharedLinkPasswordResolver = resolve;
      });
    },

    prepareShareDialogState(this: any) {
      this.clearShareCopyButtonResetTimer();
      this.clearShareLinkRefreshTimer();
      this.shareLinkGenerationRequestId += 1;

      if (refs.shareLinkModeLinkInput) {
        refs.shareLinkModeLinkInput.checked = true;
      }

      if (refs.shareLinkEncryptionToggle) {
        refs.shareLinkEncryptionToggle.checked = false;
      }

      if (refs.shareLinkPasswordInput) {
        refs.shareLinkPasswordInput.value = '';
      }

      if (refs.shareLinkPasswordConfirmInput) {
        refs.shareLinkPasswordConfirmInput.value = '';
      }

      if (refs.shareLinkTextarea) {
        refs.shareLinkTextarea.value = '';
        refs.shareLinkTextarea.placeholder = '';
      }

      if (refs.shareLinkQrTextChunkLengthInput) {
        refs.shareLinkQrTextChunkLengthInput.value = String(
          SHARE_QR_TEXT_DEFAULT_CHARACTERS_PER_CHUNK,
        );
      }

      this.closeShareLinkQrFullscreen();
      this.updateShareEncryptionFieldsVisibility();
      this.resetShareLinkQrPreview();
      this.resetShareLinkQrFullscreen();
      this.updateShareOutputModeVisibility();
      this.setShareLinkMessage(
        'Password encryption is off. This link will use plain base64 markdown.',
      );
      this.setShareCopyButtonState('idle', { disabled: true });
    },

    handleShareEncryptionToggleChange(this: any) {
      const isEncryptionEnabled = Boolean(
        refs.shareLinkEncryptionToggle?.checked,
      );

      if (!isEncryptionEnabled) {
        if (refs.shareLinkPasswordInput) {
          refs.shareLinkPasswordInput.value = '';
        }

        if (refs.shareLinkPasswordConfirmInput) {
          refs.shareLinkPasswordConfirmInput.value = '';
        }
      }

      this.updateShareEncryptionFieldsVisibility();
      void this.refreshShareLink({ selectText: false });

      if (isEncryptionEnabled) {
        this.focusDocumentElement(refs.shareLinkPasswordInput, {
          preventScroll: true,
        });
      }
    },

    handleShareEncryptionInput(this: any) {
      this.clearShareCopyButtonResetTimer();
      this.setShareCopyButtonState('idle', { disabled: true });
      this.scheduleShareLinkRefresh();
    },
  });
}

export { applyDocumentControllerShareUiMethods };
