import {
  CHORD_ANNOTATION_RE,
  CHORD_SYMBOL_RE,
  getLeadingSpaceLikeLength,
  hasChordProgressionText,
  INSTRUMENTAL_DIRECTIVE_RE,
  INTRO_DIRECTIVE_RE,
  INTRO_OR_CUE_DIRECTIVE_RE,
  isSpaceLikeCharacter,
  LANGUAGE_ID,
  MARKER_OWNER,
  REPEAT_SUFFIX_RE,
  trimSpaceLikeStart,
  trimSpaceLikeText,
  VALIDATION_DELAY_MS,
  escapeRegex,
  grammar,
  isValidStrummingPatternValue,
  normalizeConfigFieldName,
  setErrorCount,
  shouldAllowInvisibleWordSeparators,
  state,
} from '../../../editor/scripts/shared.ts';
import {
  getFenceHeaderError,
  getRequiredDeclaredPartNames,
  parseFenceHeader,
} from '../domain/parser/fences.ts';
import {
  findAdjacentDuplicateStructureError,
  parseStructureValue,
} from '../domain/structure.ts';

const {
  CONFIG_ENUM_FIELD_VALUES,
  CONFIG_FIELD_NAMES,
  CONFIG_FIELD_MATCH_NAMES,
  CONFIG_MULTILINE_FIELD_NAMES,
  CONFIG_PATTERN_FIELD_VALUES,
  CONFIG_REQUIRED_FIELD_NAMES,
} = grammar;

const CONFIG_ENTRY_RE = new RegExp(
  `^\\s*-\\s*(${CONFIG_FIELD_MATCH_NAMES.map(escapeRegex).join('|')})\\s*:(.*)$`,
);
const CONFIG_FIELD_LINE_RE = /^\s*-\s*([^:]+?)(?::(.*))?$/;
const ATTACHMENT_URL_SCHEME_SOURCE = String.raw`[A-Za-z][A-Za-z0-9+.-]*:\/\/`;
const ATTACHMENT_SOURCE_URL_SOURCE = String.raw`(?:${ATTACHMENT_URL_SCHEME_SOURCE}\S[^\r\n]*)`;
const ATTACHMENT_MARKDOWN_URL_SOURCE = String.raw`(?:${ATTACHMENT_URL_SCHEME_SOURCE}\S[^\r\n)]*)`;
const ATTACHMENT_VALUE_SOURCE = String.raw`(?:${ATTACHMENT_SOURCE_URL_SOURCE}|\[[^\]\r\n]+\]\(${ATTACHMENT_MARKDOWN_URL_SOURCE}\))`;
const ATTACHMENT_VALUE_RE = new RegExp(`^${ATTACHMENT_VALUE_SOURCE}$`);
const STRUMMING_PATTERN_MESSAGE =
  'Strumming Patterns must use only d, D, v, V, u, U, ^, x, X, 1, *, +, -, _, ., 0, bar separators (|), and spaces or tabs.';
const STRUMMING_PATTERN_CONTINUATION_MESSAGE =
  'Strumming Patterns continuation lines must start with spaces or tabs and use only d, D, v, V, u, U, ^, x, X, 1, *, +, -, _, ., 0, bar separators (|), and spaces or tabs.';
const MARKER_SEVERITY_ERROR_FALLBACK = 8;

function getErrorMarkerSeverity() {
  return (
    globalThis.monaco?.MarkerSeverity?.Error ?? MARKER_SEVERITY_ERROR_FALLBACK
  );
}

function createMarker(
  lineNumber,
  startColumn,
  endColumn,
  message,
  severity = getErrorMarkerSeverity(),
) {
  return {
    severity,
    source: LANGUAGE_ID,
    message,
    startLineNumber: lineNumber,
    startColumn: Math.max(1, startColumn),
    endLineNumber: lineNumber,
    endColumn: Math.max(startColumn + 1, endColumn),
  };
}

function createDocumentMarker(
  lines,
  message,
  severity = getErrorMarkerSeverity(),
  allowZwspSeparators = true,
) {
  const firstContentLineIndex = lines.findIndex((line) =>
    trimSpaceLikeText(line, allowZwspSeparators),
  );
  const lineIndex = firstContentLineIndex === -1 ? 0 : firstContentLineIndex;
  const line = lines[lineIndex] || '';
  const startColumn = trimSpaceLikeText(line, allowZwspSeparators)
    ? getNonWhitespaceColumn(line, allowZwspSeparators)
    : 1;
  const endColumn = trimSpaceLikeText(line, allowZwspSeparators)
    ? line.length + 1
    : 2;

  return createMarker(lineIndex + 1, startColumn, endColumn, message, severity);
}

function getNonWhitespaceColumn(line, allowZwspSeparators = true) {
  let index = 0;

  while (
    index < line.length &&
    isSpaceLikeCharacter(line[index], allowZwspSeparators)
  ) {
    index += 1;
  }

  return index >= line.length ? 1 : index + 1;
}

function isCommentLine(line, allowZwspSeparators = true) {
  return trimSpaceLikeStart(line, allowZwspSeparators).startsWith('//');
}

function buildJoinedText(lines, startLineNumber, allowZwspSeparators = true) {
  let text = '';
  const positions = [];
  let hasContent = false;

  lines.forEach((line, index) => {
    if (isCommentLine(line, allowZwspSeparators)) {
      return;
    }

    const trimmed = trimSpaceLikeText(line, allowZwspSeparators);
    if (!trimmed) {
      return;
    }

    if (hasContent) {
      text += ' ';
      positions.push({
        lineNumber: startLineNumber + index,
        column: 1,
      });
    }

    const startColumn = getNonWhitespaceColumn(line, allowZwspSeparators);
    for (let offset = 0; offset < trimmed.length; offset += 1) {
      text += trimmed[offset];
      positions.push({
        lineNumber: startLineNumber + index,
        column: startColumn + offset,
      });
    }

    hasContent = true;
  });

  return { text, positions };
}

function pushJoinedMarker(
  markers,
  joined,
  startOffset,
  endOffset,
  message,
  severity = getErrorMarkerSeverity(),
) {
  if (!joined.positions.length) {
    return;
  }

  const startIndex = Math.min(
    Math.max(0, startOffset),
    joined.positions.length - 1,
  );
  const endIndex = Math.min(
    Math.max(startIndex, endOffset - 1),
    joined.positions.length - 1,
  );
  const start = joined.positions[startIndex];
  const end = joined.positions[endIndex];

  markers.push({
    severity,
    source: LANGUAGE_ID,
    message,
    startLineNumber: start.lineNumber,
    startColumn: start.column,
    endLineNumber: end.lineNumber,
    endColumn: end.column + 1,
  });
}

function skipSpaces(text, startOffset, allowZwspSeparators = true) {
  let offset = startOffset;

  while (
    offset < text.length &&
    isSpaceLikeCharacter(text[offset], allowZwspSeparators)
  ) {
    offset += 1;
  }

  return offset;
}

function findTokenBoundary(
  text,
  startOffset,
  allowZwspSeparators = true,
  allowArrowBoundary = false,
) {
  let offset = startOffset;

  while (offset < text.length) {
    if (isSpaceLikeCharacter(text[offset], allowZwspSeparators)) {
      break;
    }

    if (
      allowArrowBoundary &&
      (text.startsWith('->', offset) || text.startsWith('=>', offset))
    ) {
      break;
    }

    offset += 1;
  }

  return Math.max(startOffset + 1, offset);
}

function findClosingBrace(text, startOffset) {
  const closingIndex = text.indexOf('}', startOffset + 1);
  return closingIndex === -1 ? text.length : closingIndex + 1;
}

function getChordAnnotationMessage(annotation, allowZwspSeparators = true) {
  const innerText = trimSpaceLikeText(
    annotation.slice(1, -1),
    allowZwspSeparators,
  );
  const suggestedChord = innerText.match(CHORD_SYMBOL_RE)?.[0] || '';

  if (suggestedChord && suggestedChord !== innerText) {
    return `Invalid chord annotation. Try [${suggestedChord}].`;
  }

  return 'Invalid chord annotation.';
}

function validateStructureValue(
  valueText,
  lineNumber,
  valueColumn,
  markers,
  declaredParts,
) {
  const parsedStructure = parseStructureValue(valueText);
  if (parsedStructure.error) {
    markers.push(
      createMarker(
        lineNumber,
        valueColumn + parsedStructure.error.startOffset,
        valueColumn + parsedStructure.error.endOffset,
        parsedStructure.error.message,
      ),
    );
    return;
  }

  const adjacentDuplicateError = findAdjacentDuplicateStructureError(
    parsedStructure.steps,
  );
  if (adjacentDuplicateError) {
    markers.push(
      createMarker(
        lineNumber,
        valueColumn + adjacentDuplicateError.startOffset,
        valueColumn + adjacentDuplicateError.endOffset,
        adjacentDuplicateError.message,
      ),
    );
    return;
  }

  parsedStructure.steps.some((step) => {
    if (declaredParts.has(step.partName)) {
      return false;
    }

    markers.push(
      createMarker(
        lineNumber,
        valueColumn + step.startOffset,
        valueColumn + step.endOffset,
        `Structure references undeclared ol part. ${step.partName} is not declared.`,
      ),
    );
    return true;
  });
}

function validateConfigBlock(
  bodyLines,
  startLineNumber,
  markers,
  declaredParts,
  allowZwspSeparators = true,
) {
  const multilineFieldNames = new Set(CONFIG_MULTILINE_FIELD_NAMES);
  const seenFieldLines = new Map();
  let activeMultilineField = '';

  bodyLines.forEach((line, index) => {
    if (isCommentLine(line, allowZwspSeparators)) {
      return;
    }

    const lineNumber = startLineNumber + index;
    const trimmedLine = trimSpaceLikeText(line, allowZwspSeparators);

    if (!trimmedLine) {
      return;
    }

    const configEntryMatch = line.match(CONFIG_ENTRY_RE);
    if (configEntryMatch) {
      const rawFieldName = configEntryMatch[1].trim();
      const fieldName = normalizeConfigFieldName(rawFieldName);
      const valueText = trimSpaceLikeText(
        configEntryMatch[2],
        allowZwspSeparators,
      );
      const separatorOffset = line.indexOf(':');
      const valueOffset =
        separatorOffset === -1 ? line.length : separatorOffset + 1;
      const valueIndentLength = getLeadingSpaceLikeLength(
        line.slice(valueOffset),
        allowZwspSeparators,
      );
      const valueColumn = valueOffset + valueIndentLength + 1;
      const existingLineNumber = seenFieldLines.get(fieldName);

      if (existingLineNumber) {
        const fieldStartColumn = line.indexOf(rawFieldName) + 1;
        markers.push(
          createMarker(
            lineNumber,
            fieldStartColumn,
            fieldStartColumn + rawFieldName.length,
            `Duplicate config field. ${fieldName} is already declared on line ${existingLineNumber}.`,
          ),
        );
        activeMultilineField = multilineFieldNames.has(fieldName)
          ? fieldName
          : '';
        return;
      }

      seenFieldLines.set(fieldName, lineNumber);

      if (!valueText && !multilineFieldNames.has(fieldName)) {
        const colonColumn = line.indexOf(':') + 1;
        markers.push(
          createMarker(
            lineNumber,
            colonColumn,
            Math.max(colonColumn + 1, line.length + 1),
            `${fieldName} must provide a value on the same line.`,
          ),
        );
      }

      if (
        fieldName === 'Attachments' &&
        valueText &&
        !ATTACHMENT_VALUE_RE.test(valueText)
      ) {
        const colonColumn = line.indexOf(':') + 1;
        markers.push(
          createMarker(
            lineNumber,
            colonColumn,
            Math.max(colonColumn + 1, line.length + 1),
            'Attachments must use a protocol-based URL such as http://, https://, file:///, ftp://, ftps://, or a Markdown link whose target is such a URL. Spaces inside the URL are allowed.',
          ),
        );
      }

      if (
        fieldName === 'Strumming Patterns' &&
        valueText &&
        !isValidStrummingPatternValue(valueText, allowZwspSeparators)
      ) {
        const colonColumn = line.indexOf(':') + 1;
        markers.push(
          createMarker(
            lineNumber,
            colonColumn,
            Math.max(colonColumn + 1, line.length + 1),
            STRUMMING_PATTERN_MESSAGE,
          ),
        );
      }

      const allowedValues = CONFIG_ENUM_FIELD_VALUES[fieldName];
      if (allowedValues && valueText && !allowedValues.includes(valueText)) {
        const colonColumn = line.indexOf(':') + 1;
        markers.push(
          createMarker(
            lineNumber,
            colonColumn,
            Math.max(colonColumn + 1, line.length + 1),
            `${fieldName} must be one of: ${allowedValues.join(', ')}.`,
          ),
        );
      }

      const valuePattern = CONFIG_PATTERN_FIELD_VALUES[fieldName];
      if (valuePattern && valueText && !valuePattern.test(valueText)) {
        const colonColumn = line.indexOf(':') + 1;
        markers.push(
          createMarker(
            lineNumber,
            colonColumn,
            Math.max(colonColumn + 1, line.length + 1),
            `${fieldName} must match [1-9]\\d*bpm.`,
          ),
        );
      }

      if (fieldName === 'Structure' && valueText) {
        validateStructureValue(
          valueText,
          lineNumber,
          valueColumn,
          markers,
          declaredParts,
        );
      }

      activeMultilineField = multilineFieldNames.has(fieldName)
        ? fieldName
        : '';
      return;
    }

    const malformedFieldMatch = /^[ \t]+/.test(line)
      ? null
      : line.match(CONFIG_FIELD_LINE_RE);
    if (malformedFieldMatch) {
      const rawFieldName = malformedFieldMatch[1].trim();
      const fieldName = normalizeConfigFieldName(rawFieldName);
      const fieldStartColumn = line.indexOf('-') + 3;
      const fieldEndColumn =
        fieldStartColumn + Math.max(1, rawFieldName.length);

      if (rawFieldName && !CONFIG_FIELD_NAMES.includes(fieldName)) {
        markers.push(
          createMarker(
            lineNumber,
            fieldStartColumn,
            fieldEndColumn,
            'Unsupported config field. Use Title, Subtitle, Description, Artist, Copyright, Key, Tempo, Time, Theme, Structure, Genre, Style, Attachments, or Strumming Patterns.',
          ),
        );
      } else {
        markers.push(
          createMarker(
            lineNumber,
            1,
            Math.max(4, line.length + 1),
            'Invalid config entry. Use - Field: value.',
          ),
        );
      }

      activeMultilineField = '';
      return;
    }

    if (!activeMultilineField) {
      const startColumn = getNonWhitespaceColumn(line, allowZwspSeparators);
      markers.push(
        createMarker(
          lineNumber,
          startColumn,
          Math.max(startColumn + 1, line.length + 1),
          'Config continuation lines must follow a Description, Attachments, or Strumming Patterns entry.',
        ),
      );
    } else if (
      activeMultilineField === 'Attachments' &&
      (!/^[ \t]+/.test(line) || !ATTACHMENT_VALUE_RE.test(trimmedLine))
    ) {
      const startColumn = getNonWhitespaceColumn(line, allowZwspSeparators);
      markers.push(
        createMarker(
          lineNumber,
          startColumn,
          Math.max(startColumn + 1, line.length + 1),
          'Attachments continuation lines must start with spaces or tabs and contain a protocol-based URL such as http://, https://, file:///, ftp://, ftps://, or a Markdown link that points to one. Spaces inside the URL are allowed.',
        ),
      );
    } else if (
      activeMultilineField === 'Strumming Patterns' &&
      (!/^[ \t]+/.test(line) ||
        !isValidStrummingPatternValue(trimmedLine, allowZwspSeparators))
    ) {
      const startColumn = getNonWhitespaceColumn(line, allowZwspSeparators);
      markers.push(
        createMarker(
          lineNumber,
          startColumn,
          Math.max(startColumn + 1, line.length + 1),
          STRUMMING_PATTERN_CONTINUATION_MESSAGE,
        ),
      );
    }
  });

  const missingRequiredFields = CONFIG_REQUIRED_FIELD_NAMES.filter(
    (fieldName) => !seenFieldLines.has(fieldName),
  );
  if (missingRequiredFields.length) {
    const headerLineNumber = Math.max(1, startLineNumber - 1);
    markers.push(
      createMarker(
        headerLineNumber,
        1,
        12,
        `Missing required config fields: ${missingRequiredFields.join(', ')}.`,
      ),
    );
  }
}

function validateProgressionTokens(
  joined,
  startOffset,
  markers,
  sectionLabel,
  allowZwspSeparators = true,
) {
  const text = joined.text;
  let offset = startOffset;

  while (offset < text.length) {
    offset = skipSpaces(text, offset, allowZwspSeparators);
    if (offset >= text.length) {
      return;
    }

    const remaining = text.slice(offset);

    const repeatMatch = remaining.match(REPEAT_SUFFIX_RE);
    if (repeatMatch) {
      offset += repeatMatch[0].length;
      continue;
    }

    if (text[offset] === '(') {
      const closingIndex = text.indexOf(')', offset + 1);
      if (closingIndex === -1) {
        pushJoinedMarker(
          markers,
          joined,
          offset,
          text.length,
          'Unclosed repeat suffix.',
        );
        return;
      }

      const suffixText = text.slice(offset + 1, closingIndex);
      const message = isRepeatLikeText(suffixText)
        ? 'Repeat suffix must use exact format (2x).'
        : `Invalid ${sectionLabel.toLowerCase()} token.`;

      pushJoinedMarker(markers, joined, offset, closingIndex + 1, message);
      return;
    }

    const barMatch = remaining.match(/^(?:\|\|:|\|:|:\|\||:\||\|)/);
    if (barMatch) {
      offset += barMatch[0].length;
      continue;
    }

    const chordMatch = remaining.match(CHORD_SYMBOL_RE);
    if (chordMatch) {
      offset += chordMatch[0].length;
      continue;
    }

    const endOffset = findTokenBoundary(text, offset, allowZwspSeparators);
    pushJoinedMarker(
      markers,
      joined,
      offset,
      endOffset,
      `Invalid ${sectionLabel.toLowerCase()} token.`,
    );
    offset = endOffset;
  }
}

function validateDirectiveBlock(
  bodyLines,
  startLineNumber,
  markers,
  sectionLabel,
  directivePattern,
  directiveExample,
  allowZwspSeparators = true,
) {
  const joined = buildJoinedText(
    bodyLines,
    startLineNumber,
    allowZwspSeparators,
  );
  if (!joined.text) {
    return;
  }

  const text = joined.text;
  let offset = skipSpaces(text, 0, allowZwspSeparators);

  if (offset < text.length && text[offset] === '{') {
    const directiveMatch = text.slice(offset).match(directivePattern);
    if (!directiveMatch) {
      pushJoinedMarker(
        markers,
        joined,
        offset,
        findClosingBrace(text, offset),
        `Invalid ${sectionLabel.toLowerCase()} directive. Expected ${directiveExample}.`,
      );
      return;
    }

    offset += directiveMatch[0].length;
  }

  offset = skipSpaces(text, offset, allowZwspSeparators);
  if (offset >= text.length) {
    return;
  }

  validateProgressionTokens(
    joined,
    offset,
    markers,
    sectionLabel,
    allowZwspSeparators,
  );
}

function validateLyricBlock(
  bodyLines,
  startLineNumber,
  markers,
  allowZwspSeparators = true,
) {
  bodyLines.forEach((line, index) => {
    if (isCommentLine(line, allowZwspSeparators)) {
      return;
    }

    if (!trimSpaceLikeText(line, allowZwspSeparators)) {
      return;
    }

    const lineNumber = startLineNumber + index;
    let offset = 0;

    while (offset < line.length) {
      const currentChar = line[offset];

      if (currentChar === '|') {
        offset += 1;
        continue;
      }

      if (currentChar === '[') {
        const closingIndex = line.indexOf(']', offset + 1);
        if (closingIndex === -1) {
          markers.push(
            createMarker(
              lineNumber,
              offset + 1,
              line.length + 1,
              'Unclosed chord annotation.',
            ),
          );
          return;
        }

        const annotation = line.slice(offset, closingIndex + 1);
        if (!CHORD_ANNOTATION_RE.test(annotation)) {
          markers.push(
            createMarker(
              lineNumber,
              offset + 1,
              closingIndex + 2,
              getChordAnnotationMessage(annotation, allowZwspSeparators),
            ),
          );
        }

        offset = closingIndex + 1;
        continue;
      }

      if (currentChar === ']') {
        markers.push(
          createMarker(
            lineNumber,
            offset + 1,
            offset + 2,
            'Unexpected closing bracket in lyric line.',
          ),
        );
      }

      offset += 1;
    }
  });
}

function isOutroProgressionLine(line, allowZwspSeparators = true) {
  const trimmedLine = trimSpaceLikeText(line, allowZwspSeparators);
  return (
    Boolean(trimmedLine) &&
    (hasChordProgressionText(trimmedLine, allowZwspSeparators) ||
      /^\{[cp]:/.test(trimmedLine))
  );
}

function validateOutroProgressionLine(
  line,
  lineNumber,
  markers,
  allowZwspSeparators = true,
) {
  const joined = buildJoinedText([line], lineNumber, allowZwspSeparators);
  if (!joined.text) {
    return;
  }

  const text = joined.text;
  let offset = skipSpaces(text, 0, allowZwspSeparators);

  if (offset < text.length && text[offset] === '{') {
    const remaining = text.slice(offset);
    const directiveMatch =
      remaining.match(INTRO_DIRECTIVE_RE) ||
      remaining.match(INSTRUMENTAL_DIRECTIVE_RE);

    if (!directiveMatch) {
      pushJoinedMarker(
        markers,
        joined,
        offset,
        findClosingBrace(text, offset),
        'Invalid outro directive. Expected {p: #3} or {c: Piano + Pads }.',
      );
      return;
    }

    offset += directiveMatch[0].length;
  }

  offset = skipSpaces(text, offset, allowZwspSeparators);
  if (offset >= text.length) {
    return;
  }

  validateProgressionTokens(
    joined,
    offset,
    markers,
    'Outro',
    allowZwspSeparators,
  );
}

function validateOutroBlock(
  bodyLines,
  startLineNumber,
  markers,
  allowZwspSeparators = true,
) {
  bodyLines.forEach((line, index) => {
    if (
      isCommentLine(line, allowZwspSeparators) ||
      !trimSpaceLikeText(line, allowZwspSeparators)
    ) {
      return;
    }

    const lineNumber = startLineNumber + index;

    if (isOutroProgressionLine(line, allowZwspSeparators)) {
      validateOutroProgressionLine(
        line,
        lineNumber,
        markers,
        allowZwspSeparators,
      );
      return;
    }

    validateLyricBlock([line], lineNumber, markers, allowZwspSeparators);
  });
}

function validateFenceBody(
  header,
  bodyLines,
  startLineNumber,
  markers,
  declaredParts,
  allowZwspSeparators = true,
) {
  header.definition.validateBody({
    header,
    bodyLines,
    startLineNumber,
    markers,
    declaredParts,
    validators: {
      validateConfigBlock: (...args) =>
        validateConfigBlock(...args, allowZwspSeparators),
      validateDirectiveBlock: (...args) =>
        validateDirectiveBlock(...args, allowZwspSeparators),
      validateLyricBlock: (...args) =>
        validateLyricBlock(...args, allowZwspSeparators),
      validateOutroBlock: (...args) =>
        validateOutroBlock(...args, allowZwspSeparators),
    },
    directivePatterns: {
      intro: INTRO_OR_CUE_DIRECTIVE_RE,
      instrumental: INSTRUMENTAL_DIRECTIVE_RE,
    },
  });
}

function collectDeclaredParts(lines) {
  const declaredParts = new Map();
  let lineIndex = 0;

  while (lineIndex < lines.length) {
    const line = lines[lineIndex];
    const headerMatch = line.match(/^\s*```ol:(.*)$/);

    if (!headerMatch) {
      lineIndex += 1;
      continue;
    }

    const info = headerMatch[1].trim();
    const header = parseFenceHeader(info);
    let closingIndex = lineIndex + 1;

    while (
      closingIndex < lines.length &&
      !/^\s*```\s*$/.test(lines[closingIndex])
    ) {
      closingIndex += 1;
    }

    if (
      header &&
      (!declaredParts.has(header.partName) ||
        header.definition.allowsDuplicateDeclaredPart())
    ) {
      declaredParts.set(header.partName, lineIndex + 1);
    }

    if (closingIndex >= lines.length) {
      break;
    }

    lineIndex = closingIndex + 1;
  }

  return declaredParts;
}

function collectMarkdownOlMarkersFromLines(lines) {
  const markers = [];
  const allowZwspSeparators = shouldAllowInvisibleWordSeparators(
    lines.join('\n'),
  );
  const declaredParts = collectDeclaredParts(lines);
  const seenParts = new Map();
  let lineIndex = 0;

  while (lineIndex < lines.length) {
    const line = lines[lineIndex];
    const headerMatch = line.match(/^\s*```ol:(.*)$/);

    if (!headerMatch) {
      lineIndex += 1;
      continue;
    }

    const info = headerMatch[1].trim();
    const header = parseFenceHeader(info);
    let closingIndex = lineIndex + 1;

    while (
      closingIndex < lines.length &&
      !/^\s*```\s*$/.test(lines[closingIndex])
    ) {
      closingIndex += 1;
    }

    const hasClosingFence = closingIndex < lines.length;
    const bodyLines = lines.slice(
      lineIndex + 1,
      hasClosingFence ? closingIndex : lines.length,
    );

    if (!header) {
      const infoOffset = Math.max(0, line.indexOf('ol:') + 3);
      markers.push(
        createMarker(
          lineIndex + 1,
          infoOffset + 1,
          Math.max(infoOffset + 2, line.length + 1),
          getFenceHeaderError(info),
        ),
      );
    } else {
      const existingLineNumber = seenParts.get(header.partName);

      if (
        existingLineNumber &&
        !header.definition.allowsDuplicateDeclaredPart()
      ) {
        const infoOffset = Math.max(0, line.indexOf('ol:') + 3);
        markers.push(
          createMarker(
            lineIndex + 1,
            infoOffset + 1,
            Math.max(infoOffset + header.partName.length + 1, line.length + 1),
            `Duplicate ol part. ${header.partName} is already declared on line ${existingLineNumber}.`,
          ),
        );
      } else {
        seenParts.set(header.partName, lineIndex + 1);
      }

      validateFenceBody(
        header,
        bodyLines,
        lineIndex + 2,
        markers,
        declaredParts,
        allowZwspSeparators,
      );
    }

    if (!hasClosingFence) {
      markers.push(
        createMarker(
          lineIndex + 1,
          1,
          Math.max(4, line.length + 1),
          'Unclosed ol fence.',
        ),
      );
      break;
    }

    lineIndex = closingIndex + 1;
  }

  getRequiredDeclaredPartNames().forEach((partName) => {
    if (!declaredParts.has(partName)) {
      markers.push(
        createDocumentMarker(
          lines,
          `Missing required ol part. Add ol:${partName}.`,
          getErrorMarkerSeverity(),
          allowZwspSeparators,
        ),
      );
    }
  });

  return markers;
}

function splitMarkdownOlText(text) {
  return String(text).replace(/\r\n?/g, '\n').split('\n');
}

function checkOLMarkdown(text) {
  if (typeof text !== 'string' && !(text instanceof String)) {
    return false;
  }

  return !collectMarkdownOlMarkersFromLines(splitMarkdownOlText(text)).some(
    (marker) => marker.severity === getErrorMarkerSeverity(),
  );
}

function validateMarkdownOlModel(model) {
  const markers = collectMarkdownOlMarkersFromLines(model.getLinesContent());
  globalThis.monaco?.editor?.setModelMarkers(model, MARKER_OWNER, markers);
  setErrorCount(
    markers.filter((marker) => marker.severity === getErrorMarkerSeverity())
      .length,
  );
}

function scheduleValidation() {
  if (!state.editor) {
    return;
  }

  window.clearTimeout(state.validationTimer);
  state.validationTimer = window.setTimeout(() => {
    const model = state.editor?.getModel();
    if (!model) {
      return;
    }

    validateMarkdownOlModel(model);
  }, VALIDATION_DELAY_MS);
}

export { checkOLMarkdown, scheduleValidation, validateMarkdownOlModel };
