function isPromiseLike(value) {
  return Boolean(value) && typeof value.then === 'function';
}

function normalizeText(value, label) {
  if (typeof value === 'string') {
    return value;
  }

  if (value === null) {
    return '';
  }

  if (value instanceof String) {
    return value.valueOf();
  }

  throw new TypeError(`${label} must be a string.`);
}

function normalizeProcessor(processor, label) {
  if (typeof processor !== 'function') {
    throw new TypeError(`${label} must be a function.`);
  }

  return processor;
}

function normalizeProcessorList(processors, label) {
  if (!processors) {
    return [];
  }

  if (Array.isArray(processors)) {
    return processors.map((processor, index) =>
      normalizeProcessor(processor, `${label}[${index}]`),
    );
  }

  return [normalizeProcessor(processors, label)];
}

function normalizeStageResult(result, label) {
  if (result === undefined) {
    return undefined;
  }

  return normalizeText(result, label);
}

function normalizeParserResult(result) {
  return normalizeText(result, 'markdown parser result');
}

function resolveProcessorOverride(
  overrideProcessors,
  defaultProcessors,
  label,
) {
  if (overrideProcessors === undefined) {
    return defaultProcessors.slice();
  }

  return normalizeProcessorList(overrideProcessors, label);
}

function resolveMarkdownParser(markdownParser) {
  if (!markdownParser) {
    return null;
  }

  if (typeof markdownParser === 'function') {
    return markdownParser;
  }

  if (typeof markdownParser.parse === 'function') {
    return markdownParser.parse.bind(markdownParser);
  }

  throw new TypeError(
    'markdownParser must be a function or an object with a parse method.',
  );
}

/**
 * Runs markdown through a configurable pipeline:
 * raw markdown -> pre-processors -> markdown parser -> post-processors -> HTML.
 */
class OLParser {
  constructor(options = {}) {
    const markdownParser =
      options.markdownParser ?? options.parser ?? options.marked ?? null;
    const preProcessors =
      options.preProcessors ??
      options.beforeParse ??
      options.beforeMarked ??
      [];
    const postProcessors =
      options.postProcessors ?? options.afterParse ?? options.afterMarked ?? [];

    this.markdownParser = null;
    this.preProcessors = [];
    this.postProcessors = [];

    this.setPreProcessors(preProcessors);
    this.setPostProcessors(postProcessors);

    if (markdownParser) {
      this.setMarkdownParser(markdownParser);
    }
  }

  setMarkdownParser(markdownParser) {
    this.markdownParser = resolveMarkdownParser(markdownParser);
    return this;
  }

  clearMarkdownParser() {
    this.markdownParser = null;
    return this;
  }

  setPreProcessors(processors) {
    this.preProcessors = normalizeProcessorList(processors, 'preProcessors');
    return this;
  }

  setBeforeMarkedProcessors(processors) {
    return this.setPreProcessors(processors);
  }

  setPostProcessors(processors) {
    this.postProcessors = normalizeProcessorList(processors, 'postProcessors');
    return this;
  }

  setAfterMarkedProcessors(processors) {
    return this.setPostProcessors(processors);
  }

  addPreProcessor(processor) {
    this.preProcessors.push(normalizeProcessor(processor, 'preProcessor'));
    return this;
  }

  addBeforeMarkedProcessor(processor) {
    return this.addPreProcessor(processor);
  }

  addPostProcessor(processor) {
    this.postProcessors.push(normalizeProcessor(processor, 'postProcessor'));
    return this;
  }

  addAfterMarkedProcessor(processor) {
    return this.addPostProcessor(processor);
  }

  addBeforeParseProcessor(processor) {
    return this.addPreProcessor(processor);
  }

  addAfterParseProcessor(processor) {
    return this.addPostProcessor(processor);
  }

  clearPreProcessors() {
    this.preProcessors = [];
    return this;
  }

  clearBeforeMarkedProcessors() {
    return this.clearPreProcessors();
  }

  clearPostProcessors() {
    this.postProcessors = [];
    return this;
  }

  clearAfterMarkedProcessors() {
    return this.clearPostProcessors();
  }

  use(stage, processor) {
    const normalizedStage = String(stage || '').toLowerCase();

    if (
      normalizedStage === 'pre' ||
      normalizedStage === 'beforeparse' ||
      normalizedStage === 'before-parse' ||
      normalizedStage === 'beforemarked' ||
      normalizedStage === 'before-marked'
    ) {
      return this.addPreProcessor(processor);
    }

    if (
      normalizedStage === 'post' ||
      normalizedStage === 'afterparse' ||
      normalizedStage === 'after-parse' ||
      normalizedStage === 'aftermarked' ||
      normalizedStage === 'after-marked'
    ) {
      return this.addPostProcessor(processor);
    }

    throw new Error(
      'Unknown stage. Use "pre", "beforeParse", "beforeMarked", "post", "afterParse", or "afterMarked".',
    );
  }

  createContext(rawText = '', extraContext = {}) {
    const normalizedRawText = normalizeText(rawText, 'raw markdown');
    const context =
      extraContext && typeof extraContext === 'object' ? extraContext : {};

    context.parser = this;
    context.rawText = normalizedRawText;
    context.markdownText = normalizedRawText;
    context.parsedHtml = '';
    context.htmlText = '';
    context.stage = 'idle';
    context.processorIndex = null;
    context.processorCount = 0;

    return context;
  }

  preprocess(rawText, context = {}) {
    const parseContext = this.createContext(rawText, context);
    const markdownText = this.runProcessorChain(
      parseContext.rawText,
      this.preProcessors,
      'preprocess',
      parseContext,
    );

    parseContext.markdownText = markdownText;
    parseContext.stage = 'complete';

    return markdownText;
  }

  beforeMarked(rawText, context = {}) {
    return this.preprocess(rawText, context);
  }

  postprocess(htmlText, context = {}) {
    const parseContext = context && typeof context === 'object' ? context : {};
    const normalizedHtmlText = normalizeText(htmlText, 'parsed html');

    parseContext.parser = this;
    parseContext.rawText =
      typeof parseContext.rawText === 'string' ? parseContext.rawText : '';
    parseContext.markdownText =
      typeof parseContext.markdownText === 'string'
        ? parseContext.markdownText
        : parseContext.rawText;
    parseContext.parsedHtml = normalizedHtmlText;
    parseContext.htmlText = normalizedHtmlText;
    parseContext.stage = 'idle';
    parseContext.processorIndex = null;
    parseContext.processorCount = 0;

    const nextHtmlText = this.runProcessorChain(
      normalizedHtmlText,
      this.postProcessors,
      'postprocess',
      parseContext,
    );

    parseContext.htmlText = nextHtmlText;
    parseContext.stage = 'complete';

    return nextHtmlText;
  }

  afterMarked(htmlText, context = {}) {
    return this.postprocess(htmlText, context);
  }

  parse(rawText, options = {}) {
    return this.parseToResult(rawText, options).htmlText;
  }

  parseToResult(rawText, options = {}) {
    const parseContext = this.createContext(rawText, options.context);
    const markdownParser = this.getMarkdownParser(
      options.markdownParser ?? options.parser ?? options.marked,
    );
    const preProcessors = resolveProcessorOverride(
      options.preProcessors ?? options.beforeParse ?? options.beforeMarked,
      this.preProcessors,
      'preProcessors',
    );
    const postProcessors = resolveProcessorOverride(
      options.postProcessors ?? options.afterParse ?? options.afterMarked,
      this.postProcessors,
      'postProcessors',
    );

    parseContext.markdownParser = markdownParser;
    parseContext.preProcessors = preProcessors.slice();
    parseContext.postProcessors = postProcessors.slice();

    const markdownText = this.runProcessorChain(
      parseContext.rawText,
      preProcessors,
      'preprocess',
      parseContext,
    );
    parseContext.markdownText = markdownText;

    parseContext.stage = 'parse';
    const parsedHtml = this.renderMarkdown(
      markdownText,
      markdownParser,
      parseContext,
    );
    parseContext.parsedHtml = parsedHtml;

    const htmlText = this.runProcessorChain(
      parsedHtml,
      postProcessors,
      'postprocess',
      parseContext,
    );
    parseContext.htmlText = htmlText;
    parseContext.stage = 'complete';
    parseContext.processorIndex = null;
    parseContext.processorCount = 0;

    return {
      rawText: parseContext.rawText,
      markdownText,
      parsedHtml,
      htmlText,
      context: parseContext,
    };
  }

  getMarkdownParser(overrideParser) {
    const markdownParser =
      overrideParser === undefined
        ? this.markdownParser
        : resolveMarkdownParser(overrideParser);

    if (!markdownParser) {
      throw new Error(
        'No markdown parser configured. Pass one to the constructor, call setMarkdownParser(), or provide options.markdownParser.',
      );
    }

    return markdownParser;
  }

  renderMarkdown(
    markdownText,
    markdownParser = this.markdownParser,
    context = {},
  ) {
    const resolvedMarkdownParser = this.getMarkdownParser(markdownParser);
    const result = resolvedMarkdownParser(markdownText, context);

    if (isPromiseLike(result)) {
      throw new TypeError(
        'markdownParser returned a Promise. OLParser only supports synchronous parsing right now.',
      );
    }

    return normalizeParserResult(result);
  }

  runProcessorChain(value, processors, stage, context) {
    let nextValue = value;

    context.stage = stage;
    context.processorCount = processors.length;

    for (let index = 0; index < processors.length; index += 1) {
      const processor = processors[index];
      context.processorIndex = index;

      const result = processor(nextValue, context);
      if (isPromiseLike(result)) {
        throw new TypeError(
          `${stage} processor at index ${index} returned a Promise. OLParser only supports synchronous processors right now.`,
        );
      }

      const normalizedResult = normalizeStageResult(
        result,
        `${stage} processor at index ${index}`,
      );

      if (normalizedResult !== undefined) {
        nextValue = normalizedResult;
      }
    }

    context.processorIndex = null;

    return nextValue;
  }
}

export { OLParser };
