import { getDefaultDraftExample } from '../../default-draft-example.ts';
import {
  DEFAULT_CONTENT,
  getCurrentValue,
  markDirty,
  refs,
  setCurrentDocumentContent,
  setSimpleEditorValue,
  setSharedDocumentDate,
  setStatus,
  state,
} from '../../shared.ts';

function applyDocumentControllerContentMethods(DocumentControllerClass) {
  Object.assign(DocumentControllerClass.prototype, {
    async initializeFromDraft(this: any) {
      const sharedDocumentResult = await this.loadSharedDocumentFromQuery();

      if (sharedDocumentResult.document) {
        state.fileName = sharedDocumentResult.document.fileName;
        setSharedDocumentDate(sharedDocumentResult.document.sharedDocumentDate);
        this.preferences.saveDraft(
          sharedDocumentResult.document.content,
          state.fileName,
          {
            sharedDocumentDate: state.sharedDocumentDate,
          },
        );
        setCurrentDocumentContent(sharedDocumentResult.document.content);
        return sharedDocumentResult.document.content;
      }

      if (sharedDocumentResult.wasPresent) {
        setSharedDocumentDate('');
        setCurrentDocumentContent(DEFAULT_CONTENT);
        return DEFAULT_CONTENT;
      }

      const savedDraft = this.preferences.loadDraft();
      if (savedDraft) {
        state.fileName = savedDraft.fileName;
        setSharedDocumentDate(savedDraft.sharedDocumentDate);
        setCurrentDocumentContent(savedDraft.content);
        return savedDraft.content;
      }

      setSharedDocumentDate('');
      setCurrentDocumentContent(DEFAULT_CONTENT);
      return DEFAULT_CONTENT;
    },

    applyDocumentContent(
      this: any,
      { content, fileName, saveDraft = true, sharedDocumentDate = '' },
    ) {
      const normalizedContent = String(content ?? '');
      const normalizedFileName =
        typeof fileName === 'string' && fileName.trim()
          ? fileName
          : 'untitled.md';
      const normalizedSharedDocumentDate =
        typeof sharedDocumentDate === 'string' ? sharedDocumentDate.trim() : '';

      this.pendingProgrammaticDocument = {
        content: normalizedContent,
        fileName: normalizedFileName,
      };

      state.fileName = normalizedFileName;
      setCurrentDocumentContent(normalizedContent);
      setSimpleEditorValue(normalizedContent);
      setSharedDocumentDate(normalizedSharedDocumentDate);
      state.openLyricStructureKeys = {};

      if (state.editor) {
        state.editor.setValue(normalizedContent);
      }

      this.previewController.renderPanels(normalizedContent);

      if (saveDraft) {
        this.preferences.saveDraft(normalizedContent, state.fileName, {
          sharedDocumentDate: state.sharedDocumentDate,
        });
      } else {
        this.preferences.clearDraft();
      }

      markDirty(false);
    },

    loadDraftExample(this: any, example = getDefaultDraftExample()) {
      const nextExample = example || getDefaultDraftExample();

      this.applyDocumentContent({
        content: nextExample.content,
        fileName: nextExample.fileName,
        saveDraft: true,
      });
    },

    bindEvents(this: any) {
      refs.openBtn?.addEventListener('click', () => {
        refs.fileInput?.click();
      });
      refs.fileInput?.addEventListener('change', this.handleFileInputChange);
      refs.saveBtn?.addEventListener('click', () => {
        this.saveCurrentDocument();
      });
      refs.downloadBtn?.addEventListener('click', () => {
        this.downloadCurrentDocument();
      });
      refs.shareLinkBtn?.addEventListener('click', () => {
        void this.openShareDialog();
      });
      refs.copyShareLinkBtn?.addEventListener('click', () => {
        void this.copyShareLink();
      });
      refs.shareLinkDialog?.addEventListener(
        'close',
        this.handleShareDialogClose,
      );
      refs.shareLinkEncryptionToggle?.addEventListener(
        'change',
        this.handleShareEncryptionToggleChange,
      );
      refs.shareLinkModeLinkInput?.addEventListener(
        'change',
        this.handleShareOutputModeChange,
      );
      refs.shareLinkModeQrLinkInput?.addEventListener(
        'change',
        this.handleShareOutputModeChange,
      );
      refs.shareLinkModeQrTextInput?.addEventListener(
        'change',
        this.handleShareOutputModeChange,
      );
      refs.shareLinkQrTextChunkLengthInput?.addEventListener(
        'change',
        this.handleShareQrTextChunkLengthChange,
      );
      refs.closeShareLinkQrFullscreenBtn?.addEventListener('click', () => {
        this.closeShareLinkQrFullscreen();
      });
      refs.shareLinkQrFullscreenDialog?.addEventListener(
        'close',
        this.handleShareQrFullscreenDialogClose,
      );
      refs.shareLinkPasswordInput?.addEventListener(
        'input',
        this.handleShareEncryptionInput,
      );
      refs.shareLinkPasswordConfirmInput?.addEventListener(
        'input',
        this.handleShareEncryptionInput,
      );
      refs.resetExampleDialog?.addEventListener(
        'close',
        this.handleResetExampleDialogClose,
      );
      refs.resetExampleList?.addEventListener(
        'change',
        this.handleResetExampleSelectionChange,
      );
      refs.loadBlankExampleBtn?.addEventListener('click', () => {
        this.loadBlankResetExample();
      });
      refs.loadSelectedExampleBtn?.addEventListener('click', () => {
        void this.loadSelectedResetExample();
      });
      refs.resetBtn?.addEventListener('click', () => {
        void this.openResetExampleDialog();
      });
      refs.parseRawTextBtn?.addEventListener('click', () => {
        this.openRawTextImportDialog();
      });
      refs.closeRawTextImportBtn?.addEventListener('click', () => {
        this.closeRawTextImportDialog();
      });
      refs.rawTextImportDialog?.addEventListener(
        'close',
        this.handleRawTextImportDialogClose,
      );
      refs.rawTextImportForm?.addEventListener(
        'submit',
        this.handleRawTextImportSubmit,
      );
    },

    handleFileInputChange(this: any, event) {
      const file = event.target.files && event.target.files[0];
      this.openFile(file);
      refs.fileInput.value = '';
    },

    saveToDisk(this: any, fileName, content) {
      const blob = new Blob([content], { type: 'text/markdown;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = fileName;
      document.body.appendChild(anchor);
      anchor.click();
      document.body.removeChild(anchor);
      URL.revokeObjectURL(url);
    },

    openFile(this: any, file) {
      if (!file) {
        return;
      }

      const reader = new FileReader();
      reader.onload = (event) => {
        const text = String(event.target?.result || '');

        if (!this.shouldOpenMarkdown(text)) {
          setStatus('Open cancelled: invalid Open Lyric markdown');
          return;
        }

        this.applyDocumentContent({
          content: text,
          fileName: file.name || 'untitled.md',
          saveDraft: true,
        });
      };
      reader.onerror = () => {
        setStatus('Failed to open file');
      };
      reader.readAsText(file);
    },

    isMarkdownFile(this: any, file) {
      if (!file || !file.name) {
        return false;
      }

      const name = file.name.toLowerCase();
      const type = (file.type || '').toLowerCase();
      return (
        name.endsWith('.md') ||
        name.endsWith('.markdown') ||
        type === 'text/markdown' ||
        type === 'text/plain'
      );
    },

    saveCurrentDocument(this: any) {
      this.saveToDisk(state.fileName, getCurrentValue());
      markDirty(false);
    },

    downloadCurrentDocument(this: any) {
      const name = prompt('Download as file name:', state.fileName);
      if (name === null) {
        return;
      }

      const safeName = name.trim() ? name.trim() : 'untitled.md';
      state.fileName = safeName.endsWith('.md') ? safeName : `${safeName}.md`;
      this.saveToDisk(state.fileName, getCurrentValue());
      markDirty(false);
    },

    resetDocument(this: any) {
      this.loadDraftExample(getDefaultDraftExample());
    },

    handleEditorContentChange(this: any, markdown) {
      setCurrentDocumentContent(markdown);

      if (
        this.pendingProgrammaticDocument &&
        this.pendingProgrammaticDocument.content === markdown &&
        this.pendingProgrammaticDocument.fileName === state.fileName
      ) {
        this.pendingProgrammaticDocument = null;
        return;
      }

      this.pendingProgrammaticDocument = null;
      this.preferences.saveDraft(markdown, state.fileName, {
        sharedDocumentDate: state.sharedDocumentDate,
      });
      markDirty(true);
    },
  });
}

export { applyDocumentControllerContentMethods };
