import { parseFenceHeader } from './parser/fences.ts';

const STRUCTURE_TOKEN_DEFINITIONS = [
  { code: 'I', header: 'Intro', allowsNumbering: false },
  { code: 'V', header: 'Verse', allowsNumbering: true },
  { code: 'P', header: 'Pre-Chorus', allowsNumbering: false },
  { code: 'C', header: 'Chorus', allowsNumbering: false },
  { code: 'X', header: 'Post-Chorus', allowsNumbering: false },
  { code: 'F', header: 'Final-Chorus', allowsNumbering: false },
  { code: 'B', header: 'Bridge', allowsNumbering: true },
  { code: 'N', header: 'Instrumental', allowsNumbering: true },
  { code: 'L', header: 'Interlude', allowsNumbering: true },
  { code: 'D', header: 'Breakdown', allowsNumbering: true },
  { code: 'R', header: 'Refrain', allowsNumbering: false },
  { code: 'T', header: 'Tag', allowsNumbering: true },
  { code: 'A', header: 'Vamp', allowsNumbering: false },
  { code: 'S', header: 'Solo', allowsNumbering: true },
  { code: 'O', header: 'Outro', allowsNumbering: false },
];

const STRUCTURE_TOKEN_DEFINITIONS_BY_CODE = new Map(
  STRUCTURE_TOKEN_DEFINITIONS.map((definition) => [
    definition.code,
    definition,
  ]),
);
const STRUCTURE_SYNTAX_EXAMPLE = 'IV1x2CV1V2CO';
const STRUCTURE_CODE_LIST = STRUCTURE_TOKEN_DEFINITIONS.map(
  (definition) => definition.code,
).join(', ');

function createStructureError(startOffset, endOffset, message) {
  return {
    startOffset,
    endOffset: Math.max(startOffset + 1, endOffset),
    message,
  };
}

function formatStructureStepLabel(step) {
  if (!step) {
    return '';
  }

  const partName = step.partName || step.partText || '';
  return step.repeatText ? `${partName} (${step.repeatText})` : partName;
}

function findAdjacentDuplicateStructureError(steps) {
  if (!Array.isArray(steps) || steps.length < 2) {
    return null;
  }

  for (let index = 1; index < steps.length; index += 1) {
    const previousStep = steps[index - 1];
    const step = steps[index];

    if (!previousStep || !step || previousStep.partName !== step.partName) {
      continue;
    }

    return createStructureError(
      step.startOffset,
      step.endOffset,
      `Structure cannot place ${step.partName} twice in a row. Increase the previous token's repeat count instead.`,
    );
  }

  return null;
}

function parseStructureValue(value) {
  const source = String(value ?? '').trim();

  if (!source) {
    return {
      text: source,
      steps: [],
      error: null,
    };
  }

  const steps = [];
  let offset = 0;

  while (offset < source.length) {
    if (/\s/.test(source[offset])) {
      return {
        text: source,
        steps,
        error: createStructureError(
          offset,
          offset + 1,
          `Structure must use compact codes like ${STRUCTURE_SYNTAX_EXAMPLE}.`,
        ),
      };
    }

    const definition = STRUCTURE_TOKEN_DEFINITIONS_BY_CODE.get(source[offset]);
    if (!definition) {
      return {
        text: source,
        steps,
        error: createStructureError(
          offset,
          offset + 1,
          `Unknown structure code. Use ${STRUCTURE_CODE_LIST}.`,
        ),
      };
    }

    const stepStartOffset = offset;
    offset += 1;

    let indexText = '';
    const indexMatch = source.slice(offset).match(/^\d+/);
    if (indexMatch) {
      indexText = indexMatch[0];

      if (!definition.allowsNumbering) {
        return {
          text: source,
          steps,
          error: createStructureError(
            offset,
            offset + indexText.length,
            `${definition.header} cannot be numbered in Structure.`,
          ),
        };
      }

      if (indexText.startsWith('0')) {
        return {
          text: source,
          steps,
          error: createStructureError(
            offset,
            offset + indexText.length,
            'Section indexes must start at 1.',
          ),
        };
      }

      offset += indexText.length;
    }

    let repeatText = '';
    if (source[offset] === 'x') {
      const repeatMatch = source.slice(offset).match(/^x(\d+)/);
      if (!repeatMatch) {
        return {
          text: source,
          steps,
          error: createStructureError(
            offset,
            offset + 1,
            'Repeat suffix must use compact format x2.',
          ),
        };
      }

      const repeatCount = repeatMatch[1];
      if (repeatCount.startsWith('0')) {
        return {
          text: source,
          steps,
          error: createStructureError(
            offset,
            offset + repeatMatch[0].length,
            'Repeat counts must start at 1.',
          ),
        };
      }

      repeatText = `${repeatCount}x`;
      offset += repeatMatch[0].length;
    }

    const partText = indexText
      ? `${definition.header} ${indexText}`
      : definition.header;
    const parsedHeader = parseFenceHeader(partText);

    steps.push({
      code: definition.code,
      definition,
      displayText: repeatText ? `${partText} (${repeatText})` : partText,
      endOffset: offset,
      header: definition.header,
      indexText,
      parsedHeader,
      partName: parsedHeader?.partName || partText,
      partText,
      rawText: source.slice(stepStartOffset, offset),
      repeatText,
      startOffset: stepStartOffset,
    });
  }

  return {
    text: source,
    steps,
    error: null,
  };
}

export {
  STRUCTURE_CODE_LIST,
  STRUCTURE_SYNTAX_EXAMPLE,
  STRUCTURE_TOKEN_DEFINITIONS,
  findAdjacentDuplicateStructureError,
  formatStructureStepLabel,
  parseStructureValue,
};
