// Self-contained chrome styling for the standalone `OpenLyric` preview
// (`editor/components/internal/OpenLyricStandaloneChrome.ts`) — the floating
// settings popup, the actions menu, the export-progress bar, and the icon
// buttons that reproduce the full page's Open Lyric preview panel (`glpp`)
// without the app shell or Bootstrap.
//
// The panel chrome rules are the SAME source the app pages use
// (`_preview-panel-chrome.scss`, included nested so they scope to this panel);
// this file only adds what a bare embed needs on top: the panel identity, the
// render-root padding, inline-SVG icon sizing, the (context-specific) progress
// bar, and minimal Bootstrap primitives (`.btn`, `.form-switch`,
// `.visually-hidden`) since the standalone page never loads Bootstrap.
// Everything the chrome renders lives under `.ol-standalone-preview`, so this
// sheet never leaks button/menu rules onto a host page.
//
// The base theme tokens the chrome consumes (`--surface`, `--accent`, …) are
// NOT defined here — the preview component injects them separately in
// standalone mode (`theme-vars-styles.ts` → `theme-vars.scss`), so they are
// shared with the bare markdown preview too and never duplicated on app pages.

@use '../../styles/preview-panel-chrome' as *;
@use '../../styles/standalone-bootstrap-shim' as *;

@keyframes ol-sc-progress-stripes {
  from {
    background-position: 1rem 0;
  }
  to {
    background-position: 0 0;
  }
}

.ol-standalone-preview {
  // Let the panel surface show through the component-owned render root, and
  // align its base text color with the app's `--ink`.
  --ol-bg: transparent;
  --ol-fg: var(--ink);

  min-height: 0;
  border: 1px solid var(--line);
  border-radius: 0.75rem;
  background: var(--surface);
  overflow: hidden;
  box-shadow: var(--shadow);
  color: var(--ink);

  &.panel--stacked {
    display: flex;
    flex-direction: column;
  }

  // The component-owned render root sits inside the panel body.
  .ol-preview-root {
    padding: 1.15rem 1.25rem 1.4rem;
    overflow-x: auto;
  }

  // Shared app chrome — floating tools, settings popup, actions menu, icon
  // buttons — scoped to this panel by the nesting.
  @include ol-preview-panel-chrome;

  // The standalone chrome draws its icons as inline SVG (the app uses the
  // bootstrap-icons webfont via `.bi`), so size the SVG off the icon box.
  .topbar-icon-btn__icon svg {
    width: 1em;
    height: 1em;
    display: block;
  }

  // Export-progress bar. Kept here rather than in the shared chrome because the
  // standalone drives its stripes off `data-state` (the app toggles Bootstrap's
  // `.progress-bar-striped`/`-animated` classes instead).
  .preview-panel__progress {
    display: grid;
    justify-items: end;
    gap: 0.28rem;
    min-width: min(100%, 13rem);
    padding: 0.5rem 0.65rem 0.58rem;
    border: 1px solid var(--line);
    border-radius: 0.9rem;
    background: color-mix(
      in srgb,
      var(--surface-elevated, var(--surface)) 92%,
      transparent
    );
    box-shadow: var(--shadow);
    backdrop-filter: blur(10px);
  }

  .preview-panel__progress[hidden] {
    display: none;
  }

  .preview-panel__progress-label {
    font-size: 0.78rem;
    line-height: 1.2;
    color: var(--muted);
    text-align: right;
  }

  .preview-panel__progress-track {
    width: min(100%, 14rem);
    height: 0.46rem;
    border-radius: 999px;
    background: var(--preview-code-bg);
    border: 1px solid var(--line);
    overflow: hidden;
  }

  .preview-panel__progress-bar {
    height: 100%;
    background: linear-gradient(
      90deg,
      var(--accent),
      var(--toolbar-icon-active-ink)
    );
    transition: width 220ms ease;
  }

  .preview-panel__progress[data-state='busy'] .preview-panel__progress-bar {
    background-image: linear-gradient(
      45deg,
      rgba(255, 255, 255, 0.22) 25%,
      transparent 25%,
      transparent 50%,
      rgba(255, 255, 255, 0.22) 50%,
      rgba(255, 255, 255, 0.22) 75%,
      transparent 75%,
      transparent
    );
    background-size: 1rem 1rem;
    animation: ol-sc-progress-stripes 1s linear infinite;
  }

  .preview-panel__progress[data-state='complete'] .preview-panel__progress-bar {
    background: linear-gradient(90deg, #16a34a, #4ade80);
  }

  .preview-panel__progress[data-state='error'] .preview-panel__progress-bar {
    background: linear-gradient(90deg, #dc2626, #fb7185);
  }

  // --- Minimal Bootstrap primitives the chrome relies on ------------------
  // Shared with the standalone editor chrome; see `_standalone-bootstrap-shim.scss`.
  @include ol-standalone-bootstrap-shim;
}
