import { getRegisteredOpenLyricSpecification } from './editor-plugin-registry.ts';

function normalizeOpenLyricApiSection(value) {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value
    : null;
}

function getOpenLyricDocumentApi() {
  return normalizeOpenLyricApiSection(
    getRegisteredOpenLyricSpecification()?.document,
  );
}

function getOpenLyricMonacoApi() {
  const monacoApi = normalizeOpenLyricApiSection(
    getRegisteredOpenLyricSpecification()?.monaco,
  );

  return normalizeOpenLyricApiSection(monacoApi?.language) || monacoApi;
}

function getOpenLyricPreviewApi() {
  return normalizeOpenLyricApiSection(
    getRegisteredOpenLyricSpecification()?.preview,
  );
}

function hasOpenLyricPlugin() {
  return Boolean(getRegisteredOpenLyricSpecification());
}

export {
  getOpenLyricDocumentApi,
  getOpenLyricMonacoApi,
  getOpenLyricPreviewApi,
  hasOpenLyricPlugin,
};
