import { STRUCTURE_TOKEN_DEFINITIONS } from '../../domain/structure.ts';

const ATTACHMENT_URL_SCHEME_SOURCE = String.raw`[A-Za-z][A-Za-z0-9+.-]*:\/\/`;
const ATTACHMENT_SOURCE_URL_SOURCE = String.raw`(?:${ATTACHMENT_URL_SCHEME_SOURCE}\S[^\r\n]*)`;
const ATTACHMENT_MARKDOWN_URL_SOURCE = String.raw`(?:${ATTACHMENT_URL_SCHEME_SOURCE}\S[^\r\n)]*)`;
const ATTACHMENT_VALUE_SOURCE = String.raw`(?:${ATTACHMENT_SOURCE_URL_SOURCE}|\[[^\]\r\n]+\]\(${ATTACHMENT_MARKDOWN_URL_SOURCE}\))`;
const ATTACHMENT_VALUE_RE = new RegExp(`^${ATTACHMENT_VALUE_SOURCE}$`);
const DECLARE_PART_POPUP_MARGIN_PX = 12;
const DECLARE_PART_POPUP_OFFSET_PX = 8;
const STRUCTURE_DEFINITIONS_BY_HEADER = new Map(
  STRUCTURE_TOKEN_DEFINITIONS.map((definition) => [
    definition.header,
    definition,
  ]),
);
const DEFAULT_TEMPO_BPM = 70;
const MIN_TEMPO_BPM = 40;
const MAX_TEMPO_BPM = 240;
const AUTO_OPEN_CONFIG_FIELD_NAMES = new Set(['Key', 'Time', 'Tempo']);
const OPEN_LYRIC_EXPORT_CONTROL_SELECTOR =
  '.ol-song-view__structure-key-control, .ol-song-view__simplify-toggle';
const OPEN_LYRIC_PRINT_WINDOW_FEATURES = 'popup=yes,width=1280,height=900';
const OPEN_LYRIC_PRINT_THEME_NAME = 'light';
const OPEN_LYRIC_PRINT_LIGHT_INK_COLOR = '#1f2a37';
const OPEN_LYRIC_PRINT_LIGHT_SURFACE_COLOR = '#ffffff';
const OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS = 6;
const OPEN_LYRIC_POWERPOINT_MAX_LINES_PER_SLIDE = 8;
const OPEN_LYRIC_POWERPOINT_DEFAULT_FONT_DETECTION_SAMPLE_TEXT =
  'WWWWmmmm1234567890OpenLyric';
const OPEN_LYRIC_POWERPOINT_GENERIC_FONT_FAMILIES = [
  'monospace',
  'sans-serif',
  'serif',
];
const OPEN_LYRIC_POWERPOINT_DEFAULT_TYPOGRAPHY = Object.freeze({
  chromeFontFace: 'Arial',
  lyricFontFace: 'Courier New',
  lyricFontSize: 24,
});

let htmlToImageModulePromise = null;
let pptxGenJsModulePromise = null;

async function loadHtmlToImageModule() {
  if (!htmlToImageModulePromise) {
    // Clear the cache on failure so a transient chunk-load error (offline blip)
    // doesn't permanently wedge exports behind a memoized rejection.
    htmlToImageModulePromise = import('html-to-image').catch((error) => {
      htmlToImageModulePromise = null;
      throw error;
    });
  }

  return htmlToImageModulePromise;
}

async function loadPptxGenJsModule() {
  if (!pptxGenJsModulePromise) {
    pptxGenJsModulePromise = import('pptxgenjs').catch((error) => {
      pptxGenJsModulePromise = null;
      throw error;
    });
  }

  return pptxGenJsModulePromise;
}

function isTransparentColor(colorValue) {
  const normalizedValue = String(colorValue ?? '')
    .trim()
    .toLowerCase();

  return (
    !normalizedValue ||
    normalizedValue === 'transparent' ||
    normalizedValue === 'rgba(0, 0, 0, 0)'
  );
}

function normalizeFontFamilyName(fontFamily) {
  return String(fontFamily ?? '')
    .trim()
    .replace(/^['"]+|['"]+$/g, '');
}

function resolveCssUrls(cssText, baseUrl) {
  return String(cssText ?? '').replace(
    /url\((['"]?)([^)'"\s][^)]*?)\1\)/g,
    (match, quote, rawUrl) => {
      const url = String(rawUrl ?? '').trim();

      if (
        !url ||
        url.startsWith('data:') ||
        url.startsWith('blob:') ||
        url.startsWith('#')
      ) {
        return match;
      }

      try {
        const resolvedUrl = new URL(url, baseUrl || document.baseURI).href;
        const wrappedQuote = quote || '"';

        return `url(${wrappedQuote}${resolvedUrl}${wrappedQuote})`;
      } catch (_error) {
        return match;
      }
    },
  );
}

function escapeStyleElementText(cssText) {
  return String(cssText ?? '').replace(/<\/style/giu, '<\\/style');
}

export {
  ATTACHMENT_VALUE_RE,
  AUTO_OPEN_CONFIG_FIELD_NAMES,
  DEFAULT_TEMPO_BPM,
  DECLARE_PART_POPUP_MARGIN_PX,
  DECLARE_PART_POPUP_OFFSET_PX,
  MAX_TEMPO_BPM,
  MIN_TEMPO_BPM,
  OPEN_LYRIC_EXPORT_CONTROL_SELECTOR,
  OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
  OPEN_LYRIC_POWERPOINT_DEFAULT_FONT_DETECTION_SAMPLE_TEXT,
  OPEN_LYRIC_POWERPOINT_DEFAULT_TYPOGRAPHY,
  OPEN_LYRIC_POWERPOINT_GENERIC_FONT_FAMILIES,
  OPEN_LYRIC_POWERPOINT_MAX_LINES_PER_SLIDE,
  OPEN_LYRIC_PRINT_LIGHT_INK_COLOR,
  OPEN_LYRIC_PRINT_LIGHT_SURFACE_COLOR,
  OPEN_LYRIC_PRINT_THEME_NAME,
  OPEN_LYRIC_PRINT_WINDOW_FEATURES,
  STRUCTURE_DEFINITIONS_BY_HEADER,
  escapeStyleElementText,
  isTransparentColor,
  loadHtmlToImageModule,
  loadPptxGenJsModule,
  normalizeFontFamilyName,
  resolveCssUrls,
};
