import { getRegisteredPowerPointStyles } from '../../../../editor/scripts/editor-plugin-registry.ts';
import { setStatus } from '../../../../editor/scripts/shared.ts';
import {
  OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
  OPEN_LYRIC_POWERPOINT_DEFAULT_FONT_DETECTION_SAMPLE_TEXT,
  OPEN_LYRIC_POWERPOINT_DEFAULT_TYPOGRAPHY,
  OPEN_LYRIC_POWERPOINT_GENERIC_FONT_FAMILIES,
  OPEN_LYRIC_POWERPOINT_MAX_LINES_PER_SLIDE,
  loadPptxGenJsModule,
  normalizeFontFamilyName,
} from './constants.ts';

function applyPreviewControllerPowerPointMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    getOpenLyricPowerPointTheme(this: any) {
      if (document.documentElement.dataset.theme === 'light') {
        return {
          accent: '0F766E',
          background: 'F7F5EF',
          body: '1F2937',
          muted: '5B6C80',
          surface: 'FFFFFF',
          surfaceBorder: 'D8E3EA',
          title: '16324F',
        };
      }

      return {
        accent: '34D399',
        background: '0D1721',
        body: 'E2E8F0',
        muted: '94A3B8',
        surface: '132434',
        surfaceBorder: '27435C',
        title: 'F8FAFC',
      };
    },

    getOpenLyricPowerPointTextBoxMargin(
      this: any,
      { left = 0, right = left, top = 0, bottom = top } = {},
    ) {
      return [left, right, bottom, top];
    },

    formatOpenLyricPowerPointFontFamily(this: any, fontFamily) {
      const normalizedFontFamily = normalizeFontFamilyName(fontFamily);

      if (!normalizedFontFamily) {
        return '';
      }

      return /[\s"'(),]/.test(normalizedFontFamily)
        ? `"${normalizedFontFamily
            .replaceAll('\\', '\\\\')
            .replaceAll('"', '\\"')}"`
        : normalizedFontFamily;
    },

    getOpenLyricPowerPointFontDetectionSampleText(this: any, pptxStyles = []) {
      const sampleTexts = (
        Array.isArray(pptxStyles) ? pptxStyles : [pptxStyles]
      )
        .map((pptxStyle) => String(pptxStyle?.fontDetectionSampleText || ''))
        .filter((sampleText) => sampleText.trim());

      return (
        sampleTexts.join(' ') ||
        OPEN_LYRIC_POWERPOINT_DEFAULT_FONT_DETECTION_SAMPLE_TEXT
      );
    },

    createOpenLyricPowerPointFontAvailabilityTester(this: any, sampleText) {
      const canvas = document.createElement('canvas');
      const context = canvas.getContext('2d');
      const effectiveSampleText =
        String(sampleText || '').trim() ||
        OPEN_LYRIC_POWERPOINT_DEFAULT_FONT_DETECTION_SAMPLE_TEXT;

      if (!context) {
        return null;
      }

      const baselineWidths = new Map(
        OPEN_LYRIC_POWERPOINT_GENERIC_FONT_FAMILIES.map(
          (fallbackFontFamily) => {
            context.font = `72px ${fallbackFontFamily}`;

            return [
              fallbackFontFamily,
              context.measureText(effectiveSampleText).width,
            ];
          },
        ),
      );

      return (fontFamily) => {
        const formattedFontFamily =
          this.formatOpenLyricPowerPointFontFamily(fontFamily);

        if (!formattedFontFamily) {
          return false;
        }

        return OPEN_LYRIC_POWERPOINT_GENERIC_FONT_FAMILIES.some(
          (fallbackFontFamily) => {
            context.font = `72px ${formattedFontFamily}, ${fallbackFontFamily}`;
            const measuredWidth =
              context.measureText(effectiveSampleText).width;

            return (
              Math.abs(
                measuredWidth - (baselineWidths.get(fallbackFontFamily) || 0),
              ) > 0.01
            );
          },
        );
      };
    },

    resolveOpenLyricPowerPointFontFace(
      this: any,
      fontFamilyChoices,
      isFontAvailable,
    ) {
      const normalizedChoices = (
        Array.isArray(fontFamilyChoices)
          ? fontFamilyChoices
          : [fontFamilyChoices]
      )
        .map((fontFamily) => normalizeFontFamilyName(fontFamily))
        .filter(Boolean);

      if (!normalizedChoices.length) {
        return '';
      }

      if (typeof isFontAvailable !== 'function') {
        return normalizedChoices[0];
      }

      return (
        normalizedChoices.find((fontFamily) => isFontAvailable(fontFamily)) ||
        ''
      );
    },

    getOpenLyricPowerPointTypography(this: any) {
      const typography = {
        ...OPEN_LYRIC_POWERPOINT_DEFAULT_TYPOGRAPHY,
      };
      const pptxStyles = getRegisteredPowerPointStyles();

      if (!pptxStyles.length) {
        return typography;
      }

      const isFontAvailable =
        this.createOpenLyricPowerPointFontAvailabilityTester(
          this.getOpenLyricPowerPointFontDetectionSampleText(pptxStyles),
        );
      let fontFaceResolved = false;
      let fontSizeResolved = false;

      pptxStyles.forEach((pptxStyle) => {
        if (!fontFaceResolved) {
          const resolvedFontFace = this.resolveOpenLyricPowerPointFontFace(
            pptxStyle.fontFamilyChoices,
            isFontAvailable,
          );

          if (resolvedFontFace) {
            typography.chromeFontFace = resolvedFontFace;
            typography.lyricFontFace = resolvedFontFace;
            fontFaceResolved = true;
          }
        }

        if (
          !fontSizeResolved &&
          Number.isFinite(pptxStyle.fontSize) &&
          pptxStyle.fontSize > 0
        ) {
          typography.lyricFontSize = pptxStyle.fontSize;
          fontSizeResolved = true;
        }
      });

      return typography;
    },

    chunkOpenLyricPowerPointLineGroups(
      this: any,
      lineGroups,
      maxLinesPerSlide = OPEN_LYRIC_POWERPOINT_MAX_LINES_PER_SLIDE,
    ) {
      const normalizedGroups = Array.isArray(lineGroups)
        ? lineGroups.map((group) => {
            if (!Array.isArray(group) || !group.length) {
              return [''];
            }

            return group.map((line) => {
              return String(line ?? '')
                .replace(/\t/g, '    ')
                .replace(/\s+$/g, '');
            });
          })
        : [];

      if (!normalizedGroups.length) {
        return [[]];
      }

      const chunks = [];
      let currentChunk = [];
      let currentLineCount = 0;

      normalizedGroups.forEach((group) => {
        const safeGroup = group.length ? group : [''];
        const groupLineCount = safeGroup.length;

        if (
          currentChunk.length &&
          currentLineCount + groupLineCount > maxLinesPerSlide
        ) {
          chunks.push(currentChunk);
          currentChunk = [];
          currentLineCount = 0;
        }

        if (
          !currentChunk.length &&
          chunks.length &&
          safeGroup.every((line) => !String(line ?? '').trim())
        ) {
          return;
        }

        currentChunk.push(safeGroup);
        currentLineCount += groupLineCount;
      });

      if (currentChunk.length) {
        chunks.push(currentChunk);
      }

      return chunks.length ? chunks : [[]];
    },

    flattenOpenLyricPowerPointChunk(this: any, chunk) {
      const lines = Array.isArray(chunk)
        ? chunk.flatMap((group) => {
            if (!Array.isArray(group) || !group.length) {
              return [''];
            }

            return group.map((line) => String(line ?? ''));
          })
        : [];
      let startIndex = 0;
      let endIndex = lines.length;

      while (startIndex < endIndex && !String(lines[startIndex] ?? '').trim()) {
        startIndex += 1;
      }

      while (
        endIndex > startIndex &&
        !String(lines[endIndex - 1] ?? '').trim()
      ) {
        endIndex -= 1;
      }

      return lines.slice(startIndex, endIndex);
    },

    buildOpenLyricPowerPointSlideTitle(
      this: any,
      sectionData,
      chunkIndex,
      totalChunks,
    ) {
      const baseTitle = sectionData?.repeatText
        ? `${sectionData.partName} (${sectionData.repeatText})`
        : sectionData?.partName || sectionData?.heading || 'Song section';

      return totalChunks > 1
        ? `${baseTitle} (${chunkIndex + 1}/${totalChunks})`
        : baseTitle;
    },

    addOpenLyricPowerPointTitleSlide(
      this: any,
      pptx,
      theme,
      presentationData,
      typography,
    ) {
      const slide = pptx.addSlide();

      slide.background = { color: theme.background };
      slide.color = theme.body;
      slide.addText('Open Lyric', {
        x: 0.75,
        y: 0.55,
        w: 3.4,
        h: 0.22,
        margin: 0,
        fontFace: typography.chromeFontFace,
        fontSize: 12,
        bold: true,
        color: theme.accent,
      });
      slide.addText(presentationData.title || 'Untitled Song', {
        x: 0.75,
        y: 1.08,
        w: 11.5,
        h: 0.75,
        margin: 0,
        fontFace: typography.chromeFontFace,
        fontSize: 28,
        bold: true,
        color: theme.title,
      });

      if (presentationData.secondaryText) {
        slide.addText(presentationData.secondaryText, {
          x: 0.75,
          y: 1.95,
          w: 11.5,
          h: 0.35,
          margin: 0,
          fontFace: typography.chromeFontFace,
          fontSize: 16,
          color: theme.muted,
        });
      }

      if (presentationData.metaLine) {
        slide.addText(presentationData.metaLine, {
          x: 0.75,
          y: 2.45,
          w: 11.4,
          h: 0.48,
          margin: this.getOpenLyricPowerPointTextBoxMargin({
            left: 10,
            right: 10,
            top: 8,
            bottom: 8,
          }),
          fontFace: typography.chromeFontFace,
          fontSize: 11,
          color: theme.body,
          fill: { color: theme.surface },
          line: { color: theme.surfaceBorder, width: 1 },
        });
      }

      slide.addText('Generated from the current Open Lyric preview', {
        x: 0.75,
        y: 6.82,
        w: 11.5,
        h: 0.2,
        margin: 0,
        fontFace: typography.chromeFontFace,
        fontSize: 9,
        color: theme.muted,
      });
    },

    addOpenLyricPowerPointMessageSlide(
      this: any,
      pptx,
      theme,
      presentationData,
      typography,
      { title, message, slideNumber, totalSlides },
    ) {
      const slide = pptx.addSlide();

      slide.background = { color: theme.background };
      slide.color = theme.body;
      slide.addText(presentationData.title || 'Open Lyric', {
        x: 0.75,
        y: 0.42,
        w: 10.8,
        h: 0.22,
        margin: 0,
        fontFace: typography.chromeFontFace,
        fontSize: 11,
        color: theme.muted,
      });
      slide.addText(title, {
        x: 0.75,
        y: 0.78,
        w: 11.25,
        h: 0.45,
        margin: 0,
        fontFace: typography.chromeFontFace,
        fontSize: 24,
        bold: true,
        color: theme.title,
      });
      slide.addText(message, {
        x: 1.05,
        y: 2.0,
        w: 11.1,
        h: 2.2,
        margin: this.getOpenLyricPowerPointTextBoxMargin({
          left: 18,
          right: 18,
          top: 12,
          bottom: 12,
        }),
        fontFace: typography.chromeFontFace,
        fontSize: 16,
        color: theme.body,
        fill: { color: theme.surface },
        line: { color: theme.surfaceBorder, width: 1 },
        align: 'center',
        valign: 'middle',
        fit: 'shrink',
      });
      slide.addText(`${slideNumber}/${totalSlides}`, {
        x: 11.55,
        y: 6.84,
        w: 0.7,
        h: 0.2,
        margin: 0,
        fontFace: typography.chromeFontFace,
        fontSize: 9,
        color: theme.muted,
        align: 'right',
      });
    },

    addOpenLyricPowerPointLyricSlide(
      this: any,
      pptx,
      theme,
      presentationData,
      typography,
      { sectionData, chunkIndex, lines, slideNumber, totalSlides, totalChunks },
    ) {
      const slide = pptx.addSlide();

      slide.background = { color: theme.background };
      slide.color = theme.body;
      slide.addText(presentationData.title || 'Open Lyric', {
        x: 0.75,
        y: 0.42,
        w: 10.8,
        h: 0.22,
        margin: 0,
        fontFace: typography.chromeFontFace,
        fontSize: 11,
        color: theme.muted,
      });
      slide.addText(
        this.buildOpenLyricPowerPointSlideTitle(
          sectionData,
          chunkIndex,
          totalChunks,
        ),
        {
          x: 0.75,
          y: 0.78,
          w: 11.25,
          h: 0.45,
          margin: 0,
          fontFace: typography.chromeFontFace,
          fontSize: 24,
          bold: true,
          color: theme.title,
        },
      );
      slide.addText(lines.length ? lines.join('\n') : ' ', {
        x: 1.05,
        y: 1.46,
        w: 11.1,
        h: 4.95,
        margin: this.getOpenLyricPowerPointTextBoxMargin({
          left: 24,
          right: 12,
          top: 12,
          bottom: 12,
        }),
        fontFace: typography.lyricFontFace,
        fontSize: typography.lyricFontSize,
        color: theme.body,
        fill: { color: theme.surface },
        line: { color: theme.surfaceBorder, width: 1 },
        align: 'left',
        valign: 'middle',
        fit: 'shrink',
      });
      slide.addText(`${slideNumber}/${totalSlides}`, {
        x: 11.55,
        y: 6.84,
        w: 0.7,
        h: 0.2,
        margin: 0,
        fontFace: typography.chromeFontFace,
        fontSize: 9,
        color: theme.muted,
        align: 'right',
      });
    },

    buildOpenLyricPowerPointSlideDescriptors(this: any, presentationData) {
      return (presentationData?.sections || []).flatMap((sectionData) => {
        const chunks = this.chunkOpenLyricPowerPointLineGroups(
          sectionData.lineGroups,
        );

        return chunks.map((chunk, chunkIndex) => ({
          chunkIndex,
          lines: this.flattenOpenLyricPowerPointChunk(chunk),
          sectionData,
          totalChunks: chunks.length,
        }));
      });
    },

    async downloadOpenLyricPresentationAsPowerPoint(this: any) {
      if (this.isOpenLyricActionPending) {
        return;
      }

      try {
        this.clearOpenLyricProgressResetTimer();
        this.setOpenLyricActionPending(true);
        await this.announceOpenLyricProgress('Preparing slides', 1);
        const presentationData = this.getOpenLyricPresentationData();

        if (!presentationData) {
          this.updateOpenLyricProgress({
            label: 'Open Lyric preview is empty',
            currentStep: 0,
            totalSteps: OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
            state: 'error',
          });
          this.scheduleOpenLyricProgressReset(1800);
          setStatus('Open Lyric preview is empty');
          return;
        }

        setStatus('Preparing Open Lyric PowerPoint...');
        await this.announceOpenLyricProgress('Collecting song lyrics', 2);
        const pptxModule = await loadPptxGenJsModule();
        const PptxGenJS = pptxModule.default || pptxModule;
        const pptx = new PptxGenJS();

        pptx.layout = 'LAYOUT_WIDE';
        await this.waitForFonts(document);

        await this.announceOpenLyricProgress('Building PowerPoint', 3);
        const theme = this.getOpenLyricPowerPointTheme();
        const typography = this.getOpenLyricPowerPointTypography();
        const slideDescriptors =
          this.buildOpenLyricPowerPointSlideDescriptors(presentationData);
        const totalSlides = Math.max(2, slideDescriptors.length + 1);

        this.addOpenLyricPowerPointTitleSlide(
          pptx,
          theme,
          presentationData,
          typography,
        );
        await this.announceOpenLyricProgress('Adding slides', 4);

        if (!slideDescriptors.length) {
          this.addOpenLyricPowerPointMessageSlide(
            pptx,
            theme,
            presentationData,
            typography,
            {
              message:
                'No structured sections are available in the current Open Lyric preview.',
              slideNumber: 2,
              title: 'No lyric slides available',
              totalSlides,
            },
          );
        } else {
          slideDescriptors.forEach((descriptor, index) => {
            this.addOpenLyricPowerPointLyricSlide(
              pptx,
              theme,
              presentationData,
              typography,
              {
                ...descriptor,
                slideNumber: index + 2,
                totalSlides,
              },
            );
          });
        }

        this.updateOpenLyricProgress({
          label: 'Packaging presentation',
          currentStep: 5,
          totalSteps: OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
          state: 'busy',
        });
        await pptx.writeFile({
          compression: true,
          fileName: this.getOpenLyricPowerPointFileName(),
        });
        this.updateOpenLyricProgress({
          label: 'Starting download',
          currentStep: 6,
          totalSteps: OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
          state: 'complete',
        });
        this.scheduleOpenLyricProgressReset(1400);
        setStatus('Open Lyric PowerPoint downloaded');
      } catch (error) {
        console.error('Failed to export Open Lyric PowerPoint.', error);
        this.updateOpenLyricProgress({
          label: 'Conversion failed',
          currentStep: 0,
          totalSteps: OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
          state: 'error',
        });
        this.scheduleOpenLyricProgressReset(2200);
        setStatus('Failed to download Open Lyric PowerPoint');
      } finally {
        this.setOpenLyricActionPending(false);
      }
    },
  });
}

export { applyPreviewControllerPowerPointMethods };
