import { parseFenceHeader } from '../../domain/parser/fences.ts';
import {
  DEFAULT_STRUMMING_PATTERN_TEXT,
  parseStrummingPatternSteps,
  parseStrummingPatterns,
} from '../helpers.ts';
import {
  CONFIG_FIELD_NAMES,
  getLeadingSpaceLikeLength,
  isSpaceLikeCharacter,
  normalizeConfigFieldName,
  shouldAllowInvisibleWordSeparators,
  state,
  trimSpaceLikeText,
} from '../../../../editor/scripts/shared.ts';
import {
  findAdjacentDuplicateStructureError,
  parseStructureValue,
} from '../../domain/structure.ts';
import {
  ATTACHMENT_VALUE_RE,
  AUTO_OPEN_CONFIG_FIELD_NAMES,
  DEFAULT_TEMPO_BPM,
  STRUCTURE_DEFINITIONS_BY_HEADER,
} from './constants.ts';

function applyPreviewControllerConfigEditingMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    collectDeclaredPartEntries(this: any, markdown) {
      const lines = String(markdown ?? '')
        .replace(/\r\n?/g, '\n')
        .split('\n');
      const declaredParts = [];
      const seenPartNames = new Set();
      let lineIndex = 0;

      while (lineIndex < lines.length) {
        const line = lines[lineIndex];
        const headerMatch = line.match(/^\s*```ol:(.*)$/);

        if (!headerMatch) {
          lineIndex += 1;
          continue;
        }

        const parsedHeader = parseFenceHeader(headerMatch[1].trim());
        if (
          parsedHeader?.partName &&
          parsedHeader.header !== 'Config' &&
          !seenPartNames.has(parsedHeader.partName)
        ) {
          seenPartNames.add(parsedHeader.partName);
          declaredParts.push({
            header: parsedHeader.header,
            indexText: parsedHeader.indexText || '',
            partName: parsedHeader.partName,
          });
        }

        let closingIndex = lineIndex + 1;

        while (
          closingIndex < lines.length &&
          !/^\s*```\s*$/.test(lines[closingIndex])
        ) {
          closingIndex += 1;
        }

        lineIndex =
          closingIndex < lines.length ? closingIndex + 1 : lines.length;
      }

      return declaredParts;
    },

    getFirstContentColumn(this: any, text, allowZwspSeparators = true) {
      const source = String(text ?? '');
      let firstContentIndex = 0;

      while (
        firstContentIndex < source.length &&
        isSpaceLikeCharacter(source[firstContentIndex], allowZwspSeparators)
      ) {
        firstContentIndex += 1;
      }

      return firstContentIndex >= source.length ? 1 : firstContentIndex + 1;
    },

    findConfigBlock(this: any, model) {
      if (!model) {
        return null;
      }

      const lines = model.getLinesContent();
      const allowZwspSeparators = shouldAllowInvisibleWordSeparators(
        lines.join('\n'),
      );
      let lineIndex = 0;

      while (lineIndex < lines.length) {
        const headerMatch = lines[lineIndex].match(/^\s*```ol:(.*)$/);

        if (!headerMatch) {
          lineIndex += 1;
          continue;
        }

        const parsedHeader = parseFenceHeader(headerMatch[1].trim());
        let closingIndex = lineIndex + 1;

        while (
          closingIndex < lines.length &&
          !/^\s*```\s*$/.test(lines[closingIndex])
        ) {
          closingIndex += 1;
        }

        if (parsedHeader?.header === 'Config') {
          const entries = [];
          let currentEntry = null;

          for (
            let bodyLineIndex = lineIndex + 1;
            bodyLineIndex < Math.min(closingIndex, lines.length);
            bodyLineIndex += 1
          ) {
            const line = lines[bodyLineIndex];
            const fieldMatch = line.match(/^\s*-\s*([^:]+):\s*(.*)$/);

            if (fieldMatch) {
              const fieldName = normalizeConfigFieldName(fieldMatch[1]);
              const separatorOffset = line.indexOf(':');
              const valueOffset =
                separatorOffset === -1 ? line.length : separatorOffset + 1;
              const valueIndentLength = getLeadingSpaceLikeLength(
                line.slice(valueOffset),
                allowZwspSeparators,
              );
              const lineNumber = bodyLineIndex + 1;

              currentEntry = {
                allowZwspSeparators,
                fieldName,
                lineNumber,
                entryLine: line,
                endLineNumber: lineNumber,
                rawLines: [line],
                valueStartColumn: valueOffset + valueIndentLength + 1,
                values: [
                  {
                    allowZwspSeparators,
                    text: fieldMatch[2],
                    rawLine: line,
                    isEntryLine: true,
                    lineEntry: {
                      text: line,
                      lineNumber,
                      column: this.getFirstContentColumn(
                        line,
                        allowZwspSeparators,
                      ),
                    },
                    valueColumn: valueOffset + valueIndentLength + 1,
                    sourceIndex: 0,
                  },
                ],
              };
              entries.push(currentEntry);
              continue;
            }

            if (!currentEntry) {
              continue;
            }

            const lineNumber = bodyLineIndex + 1;

            currentEntry.endLineNumber = lineNumber;
            currentEntry.rawLines.push(line);
            currentEntry.values.push({
              allowZwspSeparators,
              text: trimSpaceLikeText(line, allowZwspSeparators),
              rawLine: line,
              isEntryLine: false,
              lineEntry: {
                text: line,
                lineNumber,
                column: this.getFirstContentColumn(line, allowZwspSeparators),
              },
              valueColumn: this.getFirstContentColumn(
                line,
                allowZwspSeparators,
              ),
              sourceIndex: currentEntry.values.length,
            });
          }

          return {
            headerLineNumber: lineIndex + 1,
            closingLineNumber:
              closingIndex < lines.length ? closingIndex + 1 : null,
            entries,
          };
        }

        lineIndex =
          closingIndex < lines.length ? closingIndex + 1 : lines.length;
      }

      return null;
    },

    findConfigFieldEntry(this: any, model, targetFieldName) {
      const configBlock = this.findConfigBlock(model);

      if (!configBlock) {
        return null;
      }

      const normalizedTargetFieldName =
        normalizeConfigFieldName(targetFieldName);
      return (
        configBlock.entries.find((entry) => {
          return entry.fieldName === normalizedTargetFieldName;
        }) || null
      );
    },

    replaceConfigFieldLines(this: any, model, fieldEntry, nextRawLines) {
      if (!globalThis.monaco?.Range || !nextRawLines.length) {
        return false;
      }

      const replaceRange = new globalThis.monaco.Range(
        fieldEntry.lineNumber,
        1,
        fieldEntry.endLineNumber,
        model.getLineMaxColumn(fieldEntry.endLineNumber),
      );
      const currentSelections = state.editor?.getSelections() || [];

      state.editor?.pushUndoStop();
      state.editor?.executeEdits(
        'open-lyric-preview',
        [
          {
            range: replaceRange,
            text: nextRawLines.join('\n'),
            forceMoveMarkers: true,
          },
        ],
        currentSelections,
      );
      state.editor?.pushUndoStop();
      return true;
    },

    updateConfigFieldValue(this: any, fieldName, nextValue) {
      if (!state.editor) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const fieldEntry = this.findConfigFieldEntry(model, fieldName);
      if (!fieldEntry) {
        return false;
      }

      const prefixText = String(fieldEntry.entryLine ?? '').slice(
        0,
        Math.max((fieldEntry.valueStartColumn || 1) - 1, 0),
      );
      const nextEntryLine = `${prefixText}${String(nextValue ?? '')}`;
      const nextRawLines = [nextEntryLine, ...fieldEntry.rawLines.slice(1)];

      if (
        nextRawLines.length === fieldEntry.rawLines.length &&
        nextRawLines.every((line, index) => line === fieldEntry.rawLines[index])
      ) {
        return false;
      }

      return this.replaceConfigFieldLines(model, fieldEntry, nextRawLines);
    },

    getConfigInsertLineNumber(this: any, configBlock, fieldName) {
      const normalizedFieldName = normalizeConfigFieldName(fieldName);
      const fieldIndex = CONFIG_FIELD_NAMES.indexOf(normalizedFieldName);

      if (fieldIndex === -1) {
        return configBlock?.closingLineNumber || null;
      }

      const nextEntry = configBlock?.entries.find((entry) => {
        const entryIndex = CONFIG_FIELD_NAMES.indexOf(entry.fieldName);

        return entryIndex !== -1 && entryIndex > fieldIndex;
      });

      return nextEntry?.lineNumber || configBlock?.closingLineNumber || null;
    },

    insertMissingConfigField(this: any, fieldName) {
      if (!state.editor || !globalThis.monaco?.Range) {
        return false;
      }

      const normalizedFieldName = normalizeConfigFieldName(fieldName);
      if (!CONFIG_FIELD_NAMES.includes(normalizedFieldName)) {
        return false;
      }

      this.pendingConfigFieldActivation = AUTO_OPEN_CONFIG_FIELD_NAMES.has(
        normalizedFieldName,
      )
        ? normalizedFieldName
        : '';

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const configBlock = this.findConfigBlock(model);
      if (!configBlock || !Number.isInteger(configBlock.closingLineNumber)) {
        return false;
      }

      if (
        configBlock.entries.some(
          (entry) => entry.fieldName === normalizedFieldName,
        )
      ) {
        return false;
      }

      const insertLineNumber = this.getConfigInsertLineNumber(
        configBlock,
        normalizedFieldName,
      );

      if (!Number.isInteger(insertLineNumber)) {
        return false;
      }

      const referenceEntry = configBlock.entries.find((entry) => {
        return entry.lineNumber === insertLineNumber;
      });
      const indentText =
        referenceEntry?.entryLine.match(/^[ \t]*/)?.[0] ||
        configBlock.entries[0]?.entryLine.match(/^[ \t]*/)?.[0] ||
        '';
      const nextFieldLine = `${indentText}- ${normalizedFieldName}:`;
      const replaceRange = new globalThis.monaco.Range(
        insertLineNumber,
        1,
        insertLineNumber,
        1,
      );
      const currentSelections = state.editor.getSelections() || [];

      state.editor.pushUndoStop();
      state.editor.executeEdits(
        'open-lyric-preview',
        [
          {
            range: replaceRange,
            text: `${nextFieldLine}\n`,
            forceMoveMarkers: true,
          },
        ],
        currentSelections,
      );
      state.editor.pushUndoStop();
      return true;
    },

    appendAttachmentValue(this: any, nextValue) {
      if (!state.editor) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const fieldEntry = this.findConfigFieldEntry(model, 'Attachments');
      if (!fieldEntry) {
        return false;
      }

      const normalizedValue = String(nextValue ?? '').trim();
      if (!normalizedValue) {
        return false;
      }

      const continuationIndent =
        this.getConfigFieldContinuationIndent(fieldEntry);
      const nextRawLines = fieldEntry.rawLines.concat(
        `${continuationIndent}${normalizedValue}`,
      );

      return this.replaceConfigFieldLines(model, fieldEntry, nextRawLines);
    },

    removeAttachmentValue(this: any, sourceIndex) {
      if (!state.editor) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const fieldEntry = this.findConfigFieldEntry(model, 'Attachments');
      if (!fieldEntry) {
        return false;
      }

      const normalizedSourceIndex = Number.parseInt(sourceIndex, 10);
      const attachmentValue = fieldEntry.values[normalizedSourceIndex];

      if (!Number.isInteger(normalizedSourceIndex) || !attachmentValue) {
        return false;
      }

      const nextRawLines = fieldEntry.rawLines.slice();

      if (normalizedSourceIndex === 0) {
        const colonIndex = nextRawLines[0].indexOf(':');
        nextRawLines[0] =
          colonIndex === -1
            ? nextRawLines[0]
            : nextRawLines[0].slice(0, colonIndex + 1);
        return this.replaceConfigFieldLines(model, fieldEntry, nextRawLines);
      }

      const filteredLines = nextRawLines.filter((_line, currentSourceIndex) => {
        return currentSourceIndex !== normalizedSourceIndex;
      });

      return this.replaceConfigFieldLines(model, fieldEntry, filteredLines);
    },

    normalizeAttachmentConfigValue(this: any, value) {
      return String(value ?? '').trim();
    },

    isValidAttachmentConfigValue(this: any, value) {
      const normalizedValue = this.normalizeAttachmentConfigValue(value);

      return (
        Boolean(normalizedValue) && ATTACHMENT_VALUE_RE.test(normalizedValue)
      );
    },

    normalizeTempoConfigValue(this: any, value) {
      const normalizedValue = String(value ?? '').trim();

      if (!normalizedValue) {
        return '';
      }

      const tempoMatch = normalizedValue.match(/^(\d+)(?:\s*bpm)?$/i);
      if (!tempoMatch) {
        return null;
      }

      const bpm = Number.parseInt(tempoMatch[1], 10);
      if (!Number.isInteger(bpm) || bpm < 1) {
        return null;
      }

      return `${bpm}bpm`;
    },

    getTempoBpmValue(this: any, value, fallbackBpm = DEFAULT_TEMPO_BPM) {
      const normalizedValue = this.normalizeTempoConfigValue(value);

      if (!normalizedValue) {
        return fallbackBpm;
      }

      return Number.parseInt(normalizedValue, 10) || fallbackBpm;
    },

    getConfigFieldContinuationIndent(this: any, fieldEntry) {
      const continuationLine = fieldEntry.values.find((value) => {
        return !value.isEntryLine && /^[ \t]+/.test(value.rawLine);
      });

      if (continuationLine) {
        return continuationLine.rawLine.match(/^[ \t]+/)?.[0] || '  ';
      }

      const entryIndent = fieldEntry.entryLine.match(/^[ \t]*/)?.[0] || '';
      return `${entryIndent}  `;
    },

    findStructureEntry(this: any, model) {
      const fieldEntry = this.findConfigFieldEntry(model, 'Structure');

      if (!fieldEntry) {
        return null;
      }

      return {
        lineNumber: fieldEntry.lineNumber,
        valueEndColumn: fieldEntry.entryLine.length + 1,
        valueStartColumn: fieldEntry.valueStartColumn,
        valueText: String(fieldEntry.values[0]?.text ?? '').trim(),
      };
    },

    appendStrummingPattern(this: any) {
      if (!state.editor) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const fieldEntry = this.findConfigFieldEntry(model, 'Strumming Patterns');
      if (!fieldEntry) {
        return false;
      }

      const continuationIndent =
        this.getConfigFieldContinuationIndent(fieldEntry);
      const nextRawLines = fieldEntry.rawLines.concat(
        `${continuationIndent}${DEFAULT_STRUMMING_PATTERN_TEXT}`,
      );

      return this.replaceConfigFieldLines(model, fieldEntry, nextRawLines);
    },

    duplicateStrummingPattern(this: any, patternIndex) {
      if (!state.editor) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const fieldEntry = this.findConfigFieldEntry(model, 'Strumming Patterns');
      if (!fieldEntry) {
        return false;
      }

      const patterns = parseStrummingPatterns(fieldEntry.values, {
        allowZwspSeparators: fieldEntry.allowZwspSeparators,
      });
      const normalizedPatternIndex = Number.parseInt(patternIndex, 10);
      const pattern = patterns[normalizedPatternIndex];

      if (!pattern) {
        return false;
      }

      const nextRawLines = fieldEntry.rawLines.slice();
      const duplicateLines = [];
      const insertIndex = pattern.sourceIndex + 1;

      if (Number.isInteger(pattern.labelSourceIndex)) {
        duplicateLines.push(fieldEntry.rawLines[pattern.labelSourceIndex]);
      }

      if (pattern.sourceIndex === 0) {
        const continuationIndent =
          this.getConfigFieldContinuationIndent(fieldEntry);
        duplicateLines.push(`${continuationIndent}${pattern.pattern}`);
      } else {
        duplicateLines.push(fieldEntry.rawLines[pattern.sourceIndex]);
      }

      nextRawLines.splice(insertIndex, 0, ...duplicateLines);
      return this.replaceConfigFieldLines(model, fieldEntry, nextRawLines);
    },

    removeStrummingPattern(this: any, patternIndex) {
      if (!state.editor) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const fieldEntry = this.findConfigFieldEntry(model, 'Strumming Patterns');
      if (!fieldEntry) {
        return false;
      }

      const patterns = parseStrummingPatterns(fieldEntry.values, {
        allowZwspSeparators: fieldEntry.allowZwspSeparators,
      });
      const normalizedPatternIndex = Number.parseInt(patternIndex, 10);
      const pattern = patterns[normalizedPatternIndex];

      if (!pattern) {
        return false;
      }

      const nextRawLines = fieldEntry.rawLines.slice();
      const removeIndexes = new Set([pattern.sourceIndex]);

      if (Number.isInteger(pattern.labelSourceIndex)) {
        removeIndexes.add(pattern.labelSourceIndex);
      }

      if (pattern.sourceIndex === 0) {
        const colonIndex = nextRawLines[0].indexOf(':');
        nextRawLines[0] =
          colonIndex === -1
            ? nextRawLines[0]
            : nextRawLines[0].slice(0, colonIndex + 1);
        removeIndexes.delete(0);
      }

      const filteredLines = nextRawLines.filter((_line, sourceIndex) => {
        return !removeIndexes.has(sourceIndex);
      });

      return this.replaceConfigFieldLines(model, fieldEntry, filteredLines);
    },

    getNextStrummingPatternStepCharacter(this: any, direction) {
      if (direction === 'down') {
        return 'u';
      }

      if (direction === 'up') {
        return '-';
      }

      return 'd';
    },

    toggleStrummingPatternStep(this: any, patternIndex, stepIndex) {
      if (!state.editor) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const fieldEntry = this.findConfigFieldEntry(model, 'Strumming Patterns');
      if (!fieldEntry) {
        return false;
      }

      const patterns = parseStrummingPatterns(fieldEntry.values, {
        allowZwspSeparators: fieldEntry.allowZwspSeparators,
      });
      const normalizedPatternIndex = Number.parseInt(patternIndex, 10);
      const normalizedStepIndex = Number.parseInt(stepIndex, 10);
      const pattern = patterns[normalizedPatternIndex];

      if (!pattern || !Number.isInteger(normalizedStepIndex)) {
        return false;
      }

      const steps = parseStrummingPatternSteps(pattern.pattern, {
        allowZwspSeparators: pattern.allowZwspSeparators,
      });
      const step = steps[normalizedStepIndex];

      if (!step || !Number.isInteger(step.sourceOffset)) {
        return false;
      }

      const sourceValue = fieldEntry.values[pattern.sourceIndex];
      const sourceRawLine = fieldEntry.rawLines[pattern.sourceIndex];

      if (!sourceValue || typeof sourceRawLine !== 'string') {
        return false;
      }

      const replaceIndex =
        Math.max((sourceValue.valueColumn || 1) - 1, 0) + step.sourceOffset;

      if (replaceIndex < 0 || replaceIndex >= sourceRawLine.length) {
        return false;
      }

      const nextCharacter = this.getNextStrummingPatternStepCharacter(
        step.direction,
      );
      const nextRawLine = `${sourceRawLine.slice(0, replaceIndex)}${nextCharacter}${sourceRawLine.slice(replaceIndex + 1)}`;

      if (nextRawLine === sourceRawLine) {
        return false;
      }

      const nextRawLines = fieldEntry.rawLines.slice();
      nextRawLines[pattern.sourceIndex] = nextRawLine;

      return this.replaceConfigFieldLines(model, fieldEntry, nextRawLines);
    },

    createStructurePartOption(this: any, declaredPart) {
      const definition = STRUCTURE_DEFINITIONS_BY_HEADER.get(
        declaredPart.header,
      );

      if (!definition) {
        return null;
      }

      return {
        ...declaredPart,
        token: `${definition.code}${definition.allowsNumbering ? declaredPart.indexText : ''}`,
      };
    },

    getStructureInsertIndex(this: any, actionElement) {
      const insertIndexText = actionElement?.getAttribute(
        'data-structure-insert-index',
      );

      if (insertIndexText == null || insertIndexText === '') {
        return null;
      }

      const insertIndex = Number.parseInt(insertIndexText, 10);
      return Number.isInteger(insertIndex) && insertIndex >= 0
        ? insertIndex
        : null;
    },

    getStructurePartOptions(this: any, insertIndex = null) {
      const declaredParts = this.collectDeclaredPartEntries(
        this.getCurrentValue(),
      );
      const structureEntry = this.findStructureEntry(state.editor?.getModel());
      const parsedStructure = parseStructureValue(
        structureEntry?.valueText || '',
      );
      const structureSteps = parsedStructure.error ? [] : parsedStructure.steps;
      const chosenPartNames = new Set(
        structureSteps.map((step) => step.partName),
      );
      const normalizedInsertIndex = Number.isInteger(
        Number.parseInt(insertIndex, 10),
      )
        ? Number.parseInt(insertIndex, 10)
        : structureSteps.length;
      const introPart =
        declaredParts.find((part) => part.partName === 'Intro') || null;
      const outroPart =
        declaredParts.find((part) => part.partName === 'Outro') || null;
      const bodyParts = declaredParts.filter((part) => {
        return part.partName !== 'Intro' && part.partName !== 'Outro';
      });

      return [
        introPart && !chosenPartNames.has('Intro')
          ? this.createStructurePartOption(introPart)
          : null,
        ...bodyParts.map((part) => this.createStructurePartOption(part)),
        outroPart && !chosenPartNames.has('Outro')
          ? this.createStructurePartOption(outroPart)
          : null,
      ]
        .filter(Boolean)
        .filter((option) => {
          const nextSteps = structureSteps.slice();

          nextSteps.splice(normalizedInsertIndex, 0, {
            partName: option.partName,
            startOffset: 0,
            endOffset: 0,
          });

          return !findAdjacentDuplicateStructureError(nextSteps);
        });
    },

    insertStructurePartToken(this: any, structureToken, insertIndex = null) {
      if (!state.editor || !globalThis.monaco?.Range) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const structureEntry = this.findStructureEntry(model);
      if (!structureEntry) {
        return false;
      }

      const parsedStructure = parseStructureValue(structureEntry.valueText);
      const parsedInsertedStructure = parseStructureValue(structureToken);

      if (
        parsedStructure.error ||
        parsedInsertedStructure.error ||
        parsedInsertedStructure.steps.length !== 1
      ) {
        return false;
      }

      const normalizedInsertIndex = Number.isInteger(
        Number.parseInt(insertIndex, 10),
      )
        ? Number.parseInt(insertIndex, 10)
        : parsedStructure.steps.length;

      if (
        normalizedInsertIndex < 0 ||
        normalizedInsertIndex > parsedStructure.steps.length
      ) {
        return false;
      }

      const nextSteps = parsedStructure.steps.slice();

      nextSteps.splice(
        normalizedInsertIndex,
        0,
        parsedInsertedStructure.steps[0],
      );

      if (findAdjacentDuplicateStructureError(nextSteps)) {
        return false;
      }

      const insertOffset =
        normalizedInsertIndex < parsedStructure.steps.length
          ? parsedStructure.steps[normalizedInsertIndex].startOffset
          : structureEntry.valueText.length;
      const nextValue =
        structureEntry.valueText.slice(0, insertOffset) +
        structureToken +
        structureEntry.valueText.slice(insertOffset);

      if (nextValue === structureEntry.valueText) {
        return false;
      }

      const replaceRange = new globalThis.monaco.Range(
        structureEntry.lineNumber,
        structureEntry.valueStartColumn,
        structureEntry.lineNumber,
        structureEntry.valueEndColumn,
      );
      const currentSelections = state.editor.getSelections() || [];

      state.editor.pushUndoStop();
      state.editor.executeEdits(
        'open-lyric-preview',
        [
          {
            range: replaceRange,
            text: nextValue,
            forceMoveMarkers: true,
          },
        ],
        currentSelections,
      );
      state.editor.pushUndoStop();
      return true;
    },

    updateStructureStepRepeat(this: any, stepIndex, delta) {
      if (!state.editor || !globalThis.monaco?.Range) {
        return false;
      }

      const model = state.editor.getModel();
      if (!model) {
        return false;
      }

      const structureEntry = this.findStructureEntry(model);
      if (!structureEntry) {
        return false;
      }

      const parsedStructure = parseStructureValue(structureEntry.valueText);
      const normalizedStepIndex = Number.parseInt(stepIndex, 10);
      const normalizedDelta = Number(delta);
      const step = parsedStructure.steps[normalizedStepIndex];

      if (!step || !Number.isInteger(normalizedDelta) || !normalizedDelta) {
        return false;
      }

      const currentRepeatCount = step.repeatText
        ? Number.parseInt(step.repeatText, 10)
        : 1;
      const nextRepeatCount = currentRepeatCount + normalizedDelta;

      if (normalizedDelta < 0 && currentRepeatCount === 1) {
        const nextValue =
          structureEntry.valueText.slice(0, step.startOffset) +
          structureEntry.valueText.slice(step.endOffset);

        if (nextValue === structureEntry.valueText) {
          return false;
        }

        const replaceRange = new globalThis.monaco.Range(
          structureEntry.lineNumber,
          structureEntry.valueStartColumn,
          structureEntry.lineNumber,
          structureEntry.valueEndColumn,
        );
        const currentSelections = state.editor.getSelections() || [];

        state.editor.pushUndoStop();
        state.editor.executeEdits(
          'open-lyric-preview',
          [
            {
              range: replaceRange,
              text: nextValue,
              forceMoveMarkers: true,
            },
          ],
          currentSelections,
        );
        state.editor.pushUndoStop();
        return true;
      }

      if (!Number.isInteger(nextRepeatCount) || nextRepeatCount < 1) {
        return false;
      }

      const nextToken = `${step.definition.code}${step.indexText || ''}${
        nextRepeatCount > 1 ? `x${nextRepeatCount}` : ''
      }`;
      const nextValue =
        structureEntry.valueText.slice(0, step.startOffset) +
        nextToken +
        structureEntry.valueText.slice(step.endOffset);

      if (nextValue === structureEntry.valueText) {
        return false;
      }

      const replaceRange = new globalThis.monaco.Range(
        structureEntry.lineNumber,
        structureEntry.valueStartColumn,
        structureEntry.lineNumber,
        structureEntry.valueEndColumn,
      );
      const currentSelections = state.editor.getSelections() || [];

      state.editor.pushUndoStop();
      state.editor.executeEdits(
        'open-lyric-preview',
        [
          {
            range: replaceRange,
            text: nextValue,
            forceMoveMarkers: true,
          },
        ],
        currentSelections,
      );
      state.editor.pushUndoStop();
      return true;
    },
  });
}

export { applyPreviewControllerConfigEditingMethods };
