import { OPEN_LYRIC_EDITOR_INFO } from '../../../../editor/scripts/editor-metadata.ts';
import { refs, setStatus } from '../../../../editor/scripts/shared.ts';
import { normalizeFontFamilyName } from './constants.ts';

const DOCX_ORDERED_LIST_REFERENCE = 'markdown-preview-ordered-list';
const DOCX_MAX_LIST_LEVEL = 8;
const DOCX_BLOCKQUOTE_BORDER_COLOR = '94A3B8';
const DOCX_CODE_BACKGROUND = 'EEF2F6';
const DOCX_LINK_COLOR = '0563C1';
const DOCX_TABLE_BORDER_COLOR = 'CBD5E1';
const DOCX_TABLE_HEADER_BACKGROUND = 'E2E8F0';
const DOCX_DEFAULT_BODY_FONT = 'Calibri';
const DOCX_DEFAULT_CODE_FONT = 'Consolas';
const DOCX_INDENT_STEP_TWIP = 360;
const DOCX_BLOCK_TAG_NAMES = new Set([
  'ADDRESS',
  'ARTICLE',
  'ASIDE',
  'BLOCKQUOTE',
  'DIV',
  'DL',
  'FIELDSET',
  'FIGCAPTION',
  'FIGURE',
  'FOOTER',
  'FORM',
  'H1',
  'H2',
  'H3',
  'H4',
  'H5',
  'H6',
  'HEADER',
  'HR',
  'MAIN',
  'NAV',
  'OL',
  'P',
  'PRE',
  'SECTION',
  'TABLE',
  'UL',
]);
const DOCX_GENERIC_FONT_FAMILY_NAMES = new Set([
  'serif',
  'sans-serif',
  'monospace',
  'system-ui',
  'emoji',
  'math',
  'fangsong',
  'ui-serif',
  'ui-sans-serif',
  'ui-monospace',
]);

let docxModulePromise = null;

function stripDocxExtension(value) {
  return String(value ?? '')
    .replace(/\.docx$/iu, '')
    .trim();
}

function loadDocxModule() {
  if (!docxModulePromise) {
    // Clear the cache on failure so a transient chunk-load error doesn't
    // permanently wedge DOCX export behind a memoized rejection.
    docxModulePromise = import('docx').catch((error) => {
      docxModulePromise = null;
      throw error;
    });
  }

  return docxModulePromise;
}

function clampListLevel(level) {
  return Math.max(0, Math.min(DOCX_MAX_LIST_LEVEL, Number(level) || 0));
}

function createOrderedListLevels(docxModule) {
  return Array.from({ length: DOCX_MAX_LIST_LEVEL + 1 }, (_value, level) => {
    const listLevel = clampListLevel(level);
    const numberingText = Array.from(
      { length: listLevel + 1 },
      (_entry, index) => `%${index + 1}`,
    ).join('.');

    return {
      level: listLevel,
      format: docxModule.LevelFormat.DECIMAL,
      text: `${numberingText}.`,
      alignment: docxModule.AlignmentType.START,
      style: {
        paragraph: {
          indent: {
            left: 720 * (listLevel + 1),
            hanging: 260,
          },
        },
      },
    };
  });
}

function normalizeDocxWhitespace(text, { preserveWhitespace = false } = {}) {
  const normalizedText = String(text ?? '')
    .replace(/\r\n?/gu, '\n')
    .replace(/\u00a0/gu, ' ');

  if (preserveWhitespace) {
    return normalizedText;
  }

  return normalizedText.replace(/[\t\n\f\v ]+/gu, ' ');
}

function getResolvedHref(href) {
  const value = String(href ?? '').trim();

  if (!value) {
    return '';
  }

  try {
    return new URL(value, document.baseURI).href;
  } catch (_error) {
    return value;
  }
}

function isWrapperElement(element) {
  if (!(element instanceof HTMLElement)) {
    return false;
  }

  return (
    element.id === 'preview' ||
    element.classList.contains('ol-preview-segment') ||
    element.classList.contains('ol-preview-markdown-block') ||
    element.classList.contains('markdown-preview-print-surface') ||
    element.classList.contains('open-lyric-render-surface')
  );
}

function isBlockElement(element) {
  if (!(element instanceof HTMLElement)) {
    return false;
  }

  return DOCX_BLOCK_TAG_NAMES.has(element.tagName);
}

function hasRenderableText(text, { preserveWhitespace = false } = {}) {
  const normalizedText = normalizeDocxWhitespace(text, { preserveWhitespace });

  return preserveWhitespace
    ? normalizedText.length > 0
    : normalizedText.trim().length > 0;
}

function getPreferredFontFamily(fontFamilyValue, fallbackFontFamily) {
  const preferredFontFamily = String(fontFamilyValue ?? '')
    .split(',')
    .map((fontFamily) => normalizeFontFamilyName(fontFamily))
    .map((fontFamily) => fontFamily.replace(/^editor-/iu, ''))
    .find((fontFamily) => {
      const normalizedFamily = fontFamily.toLowerCase();

      return (
        normalizedFamily &&
        !DOCX_GENERIC_FONT_FAMILY_NAMES.has(normalizedFamily)
      );
    });

  return preferredFontFamily || fallbackFontFamily;
}

function mergeRunOptions(baseOptions = {}, nextOptions = {}) {
  return {
    ...baseOptions,
    ...nextOptions,
    ...(baseOptions.underline || nextOptions.underline
      ? {
          underline: {
            ...(typeof baseOptions.underline === 'object'
              ? baseOptions.underline
              : {}),
            ...(typeof nextOptions.underline === 'object'
              ? nextOptions.underline
              : {}),
          },
        }
      : {}),
  };
}

function createTextRuns(docxModule, text, runOptions = {}, options = {}) {
  const preserveWhitespace = Boolean(options.preserveWhitespace);
  const normalizedText = normalizeDocxWhitespace(text, { preserveWhitespace });

  if (!hasRenderableText(normalizedText, { preserveWhitespace })) {
    return [];
  }

  if (!preserveWhitespace) {
    return [
      new docxModule.TextRun({
        ...runOptions,
        text: normalizedText,
      }),
    ];
  }

  const textLines = normalizedText.split('\n');

  return textLines.map((line, index) => {
    const lineText = line.length > 0 ? line : ' ';

    return new docxModule.TextRun({
      ...runOptions,
      text: lineText,
      ...(index > 0 ? { break: 1 } : {}),
    });
  });
}

function buildParagraphOptions(docxModule, context = {}, nextOptions = {}) {
  const indentLeft = Math.max(0, Number(context.indentLeftTwip) || 0);
  const paragraphOptions = {
    spacing: {
      after: 160,
    },
    ...nextOptions,
  };

  if (indentLeft > 0 || nextOptions.indent) {
    paragraphOptions.indent = {
      ...(nextOptions.indent || {}),
      left: indentLeft,
    };
  }

  if ((Number(context.quoteDepth) || 0) > 0) {
    paragraphOptions.border = {
      ...(nextOptions.border || {}),
      left: {
        color: DOCX_BLOCKQUOTE_BORDER_COLOR,
        size: 10,
        space: 8,
        style: docxModule.BorderStyle.SINGLE,
      },
    };
  }

  return paragraphOptions;
}

function createParagraphFromInlineNodes(
  docxModule,
  nodes,
  context = {},
  paragraphOptions = {},
) {
  const children = collectInlineChildren(docxModule, nodes, context);

  if (!children.length) {
    const fallbackText = normalizeDocxWhitespace(
      nodes.map((node) => node?.textContent ?? '').join(' '),
    ).trim();

    if (!fallbackText) {
      return null;
    }

    children.push(
      new docxModule.TextRun(
        mergeRunOptions(context.defaultRunOptions, {
          text: fallbackText,
        }),
      ),
    );
  }

  return new docxModule.Paragraph({
    ...buildParagraphOptions(docxModule, context, paragraphOptions),
    children,
  });
}

function collectInlineChildren(
  docxModule,
  nodes,
  context = {},
  runOptions = {},
) {
  const children = [];

  Array.from(nodes || []).forEach((node) => {
    if (node?.nodeType === Node.TEXT_NODE) {
      children.push(
        ...createTextRuns(
          docxModule,
          node.textContent,
          mergeRunOptions(context.defaultRunOptions, runOptions),
          {
            preserveWhitespace: Boolean(
              runOptions.font === context.codeFontFamily,
            ),
          },
        ),
      );
      return;
    }

    if (!(node instanceof HTMLElement)) {
      return;
    }

    switch (node.tagName) {
      case 'BR': {
        children.push(new docxModule.TextRun({ text: '', break: 1 }));
        return;
      }
      case 'STRONG':
      case 'B': {
        children.push(
          ...collectInlineChildren(
            docxModule,
            node.childNodes,
            context,
            mergeRunOptions(runOptions, { bold: true }),
          ),
        );
        return;
      }
      case 'EM':
      case 'I': {
        children.push(
          ...collectInlineChildren(
            docxModule,
            node.childNodes,
            context,
            mergeRunOptions(runOptions, { italics: true }),
          ),
        );
        return;
      }
      case 'S':
      case 'DEL': {
        children.push(
          ...collectInlineChildren(
            docxModule,
            node.childNodes,
            context,
            mergeRunOptions(runOptions, { strike: true }),
          ),
        );
        return;
      }
      case 'SUP': {
        children.push(
          ...collectInlineChildren(
            docxModule,
            node.childNodes,
            context,
            mergeRunOptions(runOptions, { superScript: true }),
          ),
        );
        return;
      }
      case 'SUB': {
        children.push(
          ...collectInlineChildren(
            docxModule,
            node.childNodes,
            context,
            mergeRunOptions(runOptions, { subScript: true }),
          ),
        );
        return;
      }
      case 'MARK': {
        children.push(
          ...collectInlineChildren(
            docxModule,
            node.childNodes,
            context,
            mergeRunOptions(runOptions, { highlight: 'yellow' }),
          ),
        );
        return;
      }
      case 'CODE': {
        children.push(
          ...createTextRuns(
            docxModule,
            node.textContent,
            mergeRunOptions(context.defaultRunOptions, {
              ...runOptions,
              font: context.codeFontFamily,
              shading: {
                fill: DOCX_CODE_BACKGROUND,
                type: docxModule.ShadingType.CLEAR,
              },
            }),
            {
              preserveWhitespace: true,
            },
          ),
        );
        return;
      }
      case 'A': {
        const link = getResolvedHref(node.getAttribute('href'));
        const linkChildren = collectInlineChildren(
          docxModule,
          node.childNodes,
          context,
          mergeRunOptions(runOptions, {
            color: DOCX_LINK_COLOR,
            underline: {
              type: docxModule.UnderlineType.SINGLE,
            },
          }),
        );

        if (!linkChildren.length) {
          const linkText = String(node.textContent ?? '').trim() || link;

          linkChildren.push(
            new docxModule.TextRun({
              ...mergeRunOptions(context.defaultRunOptions, {
                color: DOCX_LINK_COLOR,
                underline: {
                  type: docxModule.UnderlineType.SINGLE,
                },
              }),
              text: linkText,
            }),
          );
        }

        if (link) {
          children.push(
            new docxModule.ExternalHyperlink({
              link,
              children: linkChildren,
            }),
          );
          return;
        }

        children.push(...linkChildren);
        return;
      }
      case 'IMG': {
        const imageAlt = String(node.getAttribute('alt') ?? '').trim();
        const imageSource = getResolvedHref(node.getAttribute('src'));
        const imageText = imageAlt || imageSource || 'Image';

        if (imageSource) {
          children.push(
            new docxModule.ExternalHyperlink({
              link: imageSource,
              children: [
                new docxModule.TextRun({
                  ...mergeRunOptions(context.defaultRunOptions, {
                    color: DOCX_LINK_COLOR,
                    underline: {
                      type: docxModule.UnderlineType.SINGLE,
                    },
                  }),
                  text: imageText,
                }),
              ],
            }),
          );
          return;
        }

        children.push(
          new docxModule.TextRun({
            ...mergeRunOptions(context.defaultRunOptions, runOptions),
            text: imageText,
          }),
        );
        return;
      }
      default: {
        children.push(
          ...collectInlineChildren(
            docxModule,
            node.childNodes,
            context,
            runOptions,
          ),
        );
      }
    }
  });

  return children;
}

function createFallbackParagraphs(docxModule, text, context = {}) {
  const normalizedText = String(text ?? '')
    .replace(/\r\n?/gu, '\n')
    .trim();

  if (!normalizedText) {
    return [];
  }

  return normalizedText
    .split(/\n+/gu)
    .map((line) => {
      const paragraph = createParagraphFromInlineNodes(
        docxModule,
        [{ textContent: line, nodeType: Node.TEXT_NODE }],
        context,
      );

      return paragraph;
    })
    .filter(Boolean);
}

function convertListItemToBlocks(
  docxModule,
  listItemElement,
  context,
  options,
) {
  const blocks = [];
  const trailingIndentContext = {
    ...context,
    indentLeftTwip:
      (Number(context.indentLeftTwip) || 0) + DOCX_INDENT_STEP_TWIP,
  };
  let leadingNodes = [];
  let hasPrimaryParagraph = false;

  const flushPrimaryParagraph = () => {
    if (!leadingNodes.length) {
      return;
    }

    const paragraph = createParagraphFromInlineNodes(
      docxModule,
      leadingNodes,
      context,
      options.ordered
        ? {
            numbering: {
              reference: DOCX_ORDERED_LIST_REFERENCE,
              level: clampListLevel(options.level),
            },
            spacing: { after: 80 },
          }
        : {
            bullet: {
              level: clampListLevel(options.level),
            },
            spacing: { after: 80 },
          },
    );

    if (paragraph) {
      blocks.push(paragraph);
      hasPrimaryParagraph = true;
    }

    leadingNodes = [];
  };

  Array.from(listItemElement.childNodes).forEach((childNode) => {
    if (childNode instanceof HTMLElement && childNode.tagName === 'P') {
      if (!hasPrimaryParagraph) {
        leadingNodes = Array.from(childNode.childNodes);
        flushPrimaryParagraph();
      } else {
        blocks.push(
          ...convertElementToDocxBlocks(
            docxModule,
            childNode,
            trailingIndentContext,
          ),
        );
      }

      return;
    }

    if (
      childNode instanceof HTMLElement &&
      (childNode.tagName === 'UL' || childNode.tagName === 'OL')
    ) {
      flushPrimaryParagraph();
      blocks.push(
        ...convertElementToDocxBlocks(
          docxModule,
          childNode,
          {
            ...context,
            indentLeftTwip: Number(context.indentLeftTwip) || 0,
            quoteDepth: Number(context.quoteDepth) || 0,
          },
          options.level + 1,
        ),
      );
      return;
    }

    if (childNode instanceof HTMLElement && isBlockElement(childNode)) {
      flushPrimaryParagraph();
      blocks.push(
        ...convertElementToDocxBlocks(
          docxModule,
          childNode,
          trailingIndentContext,
        ),
      );
      return;
    }

    leadingNodes.push(childNode);
  });

  flushPrimaryParagraph();

  if (!blocks.length) {
    blocks.push(
      new docxModule.Paragraph(
        options.ordered
          ? {
              numbering: {
                reference: DOCX_ORDERED_LIST_REFERENCE,
                level: clampListLevel(options.level),
              },
            }
          : {
              bullet: {
                level: clampListLevel(options.level),
              },
            },
      ),
    );
  }

  return blocks;
}

function createCodeBlockParagraph(docxModule, preElement, context = {}) {
  const codeText = String(preElement.textContent ?? '')
    .replace(/\r\n?/gu, '\n')
    .replace(/\n$/u, '');
  const children = createTextRuns(
    docxModule,
    codeText || ' ',
    mergeRunOptions(context.defaultRunOptions, {
      font: context.codeFontFamily,
      shading: {
        fill: DOCX_CODE_BACKGROUND,
        type: docxModule.ShadingType.CLEAR,
      },
    }),
    {
      preserveWhitespace: true,
    },
  );

  return new docxModule.Paragraph({
    ...buildParagraphOptions(docxModule, context, {
      spacing: { after: 180 },
      shading: {
        fill: DOCX_CODE_BACKGROUND,
        type: docxModule.ShadingType.CLEAR,
      },
      indent: {
        left: (Number(context.indentLeftTwip) || 0) + 240,
      },
    }),
    children,
  });
}

function createTableCellChildren(docxModule, cellElement, context = {}) {
  const cellContext =
    cellElement.tagName === 'TH'
      ? {
          ...context,
          defaultRunOptions: mergeRunOptions(context.defaultRunOptions, {
            bold: true,
          }),
        }
      : context;
  const blocks = convertNodeListToDocxBlocks(
    docxModule,
    cellElement.childNodes,
    cellContext,
  );

  if (blocks.length) {
    return blocks;
  }

  return [new docxModule.Paragraph('')];
}

function createTableBlock(docxModule, tableElement, context = {}) {
  const rows = [];

  tableElement.querySelectorAll('tr').forEach((rowElement) => {
    if (!(rowElement instanceof HTMLTableRowElement)) {
      return;
    }

    const cells = Array.from(rowElement.children)
      .filter(
        (cellElement) =>
          cellElement instanceof HTMLTableCellElement ||
          cellElement instanceof HTMLTableColElement,
      )
      .map((cellElement) => {
        return new docxModule.TableCell({
          shading:
            cellElement instanceof HTMLTableCellElement &&
            cellElement.tagName === 'TH'
              ? {
                  fill: DOCX_TABLE_HEADER_BACKGROUND,
                  type: docxModule.ShadingType.CLEAR,
                }
              : undefined,
          children:
            cellElement instanceof HTMLTableCellElement
              ? createTableCellChildren(docxModule, cellElement, context)
              : [new docxModule.Paragraph('')],
        });
      });

    if (!cells.length) {
      return;
    }

    rows.push(new docxModule.TableRow({ children: cells }));
  });

  if (!rows.length) {
    return [];
  }

  return [
    new docxModule.Table({
      rows,
      width: {
        size: 100,
        type: docxModule.WidthType.PERCENTAGE,
      },
      borders: {
        top: {
          color: DOCX_TABLE_BORDER_COLOR,
          size: 1,
          style: docxModule.BorderStyle.SINGLE,
        },
        bottom: {
          color: DOCX_TABLE_BORDER_COLOR,
          size: 1,
          style: docxModule.BorderStyle.SINGLE,
        },
        left: {
          color: DOCX_TABLE_BORDER_COLOR,
          size: 1,
          style: docxModule.BorderStyle.SINGLE,
        },
        right: {
          color: DOCX_TABLE_BORDER_COLOR,
          size: 1,
          style: docxModule.BorderStyle.SINGLE,
        },
        insideHorizontal: {
          color: DOCX_TABLE_BORDER_COLOR,
          size: 1,
          style: docxModule.BorderStyle.SINGLE,
        },
        insideVertical: {
          color: DOCX_TABLE_BORDER_COLOR,
          size: 1,
          style: docxModule.BorderStyle.SINGLE,
        },
      },
    }),
  ];
}

function convertElementToDocxBlocks(
  docxModule,
  element,
  context = {},
  listLevel = 0,
) {
  if (!(element instanceof HTMLElement)) {
    return [];
  }

  if (element.classList.contains('ol-preview-segment')) {
    if (element.dataset.previewSegmentType === 'olFence') {
      return createFallbackParagraphs(docxModule, element.textContent, {
        ...context,
        indentLeftTwip:
          (Number(context.indentLeftTwip) || 0) + DOCX_INDENT_STEP_TWIP,
      });
    }

    return convertNodeListToDocxBlocks(docxModule, element.childNodes, context);
  }

  if (isWrapperElement(element)) {
    return convertNodeListToDocxBlocks(docxModule, element.childNodes, context);
  }

  switch (element.tagName) {
    case 'H1':
    case 'H2':
    case 'H3':
    case 'H4':
    case 'H5':
    case 'H6': {
      const headingLevel = {
        H1: docxModule.HeadingLevel.HEADING_1,
        H2: docxModule.HeadingLevel.HEADING_2,
        H3: docxModule.HeadingLevel.HEADING_3,
        H4: docxModule.HeadingLevel.HEADING_4,
        H5: docxModule.HeadingLevel.HEADING_5,
        H6: docxModule.HeadingLevel.HEADING_6,
      }[element.tagName];
      const paragraph = createParagraphFromInlineNodes(
        docxModule,
        element.childNodes,
        context,
        {
          heading: headingLevel,
          spacing: { before: 220, after: 140 },
        },
      );

      return paragraph ? [paragraph] : [];
    }
    case 'P': {
      const paragraph = createParagraphFromInlineNodes(
        docxModule,
        element.childNodes,
        context,
      );

      return paragraph ? [paragraph] : [];
    }
    case 'PRE': {
      return [createCodeBlockParagraph(docxModule, element, context)];
    }
    case 'BLOCKQUOTE': {
      return convertNodeListToDocxBlocks(docxModule, element.childNodes, {
        ...context,
        indentLeftTwip:
          (Number(context.indentLeftTwip) || 0) + DOCX_INDENT_STEP_TWIP,
        quoteDepth: (Number(context.quoteDepth) || 0) + 1,
      });
    }
    case 'UL':
    case 'OL': {
      return Array.from(element.children)
        .filter((childElement) => childElement instanceof HTMLLIElement)
        .flatMap((listItemElement) => {
          return convertListItemToBlocks(docxModule, listItemElement, context, {
            level: clampListLevel(listLevel),
            ordered: element.tagName === 'OL',
          });
        });
    }
    case 'TABLE': {
      return createTableBlock(docxModule, element, context);
    }
    case 'HR': {
      return [
        new docxModule.Paragraph({
          ...buildParagraphOptions(docxModule, context, {
            spacing: { before: 120, after: 160 },
          }),
          thematicBreak: true,
        }),
      ];
    }
    default: {
      if (isBlockElement(element)) {
        return convertNodeListToDocxBlocks(
          docxModule,
          element.childNodes,
          context,
        );
      }

      const paragraph = createParagraphFromInlineNodes(
        docxModule,
        [element],
        context,
      );

      return paragraph ? [paragraph] : [];
    }
  }
}

function convertNodeListToDocxBlocks(docxModule, nodes, context = {}) {
  const blocks = [];

  Array.from(nodes || []).forEach((node) => {
    if (node?.nodeType === Node.TEXT_NODE) {
      if (!hasRenderableText(node.textContent)) {
        return;
      }

      const paragraph = createParagraphFromInlineNodes(
        docxModule,
        [node],
        context,
      );

      if (paragraph) {
        blocks.push(paragraph);
      }
      return;
    }

    if (!(node instanceof HTMLElement)) {
      return;
    }

    blocks.push(...convertElementToDocxBlocks(docxModule, node, context));
  });

  return blocks;
}

function applyPreviewControllerDocxExportMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    getMarkdownPreviewDocxDefaultFileName(this: any) {
      const baseName = this.getMarkdownPreviewExportBaseName();

      if (baseName === 'markdown-preview') {
        return 'markdown-preview.docx';
      }

      return `${baseName}-markdown-preview.docx`;
    },

    syncMarkdownPreviewDocxFileNameInput(this: any) {
      if (
        !(refs.markdownPreviewDocxFileNameInput instanceof HTMLInputElement)
      ) {
        return;
      }

      refs.markdownPreviewDocxFileNameInput.placeholder =
        this.getMarkdownPreviewDocxDefaultFileName();
    },

    getMarkdownPreviewDocxFileName(this: any) {
      const defaultFileName = this.getMarkdownPreviewDocxDefaultFileName();

      if (
        !(refs.markdownPreviewDocxFileNameInput instanceof HTMLInputElement)
      ) {
        return defaultFileName;
      }

      const overrideBaseName = this.sanitizeOpenLyricExportName?.(
        stripDocxExtension(refs.markdownPreviewDocxFileNameInput.value),
      );

      if (!overrideBaseName) {
        return defaultFileName;
      }

      return `${overrideBaseName}.docx`;
    },

    getMarkdownPreviewDocxFontFamilies(this: any) {
      const previewStyle = refs.preview
        ? globalThis.getComputedStyle(refs.preview)
        : null;

      return {
        bodyFontFamily: getPreferredFontFamily(
          previewStyle?.fontFamily,
          DOCX_DEFAULT_BODY_FONT,
        ),
        codeFontFamily: getPreferredFontFamily(
          "Consolas, 'Courier New', monospace",
          DOCX_DEFAULT_CODE_FONT,
        ),
      };
    },

    buildMarkdownPreviewDocxDocument(this: any, previewRoot, docxModule) {
      const title = this.getMarkdownPreviewExportBaseName();
      const { bodyFontFamily, codeFontFamily } =
        this.getMarkdownPreviewDocxFontFamilies();
      const documentChildren = convertNodeListToDocxBlocks(
        docxModule,
        previewRoot?.childNodes || [],
        {
          bodyFontFamily,
          codeFontFamily,
          defaultRunOptions: {
            font: bodyFontFamily,
          },
          indentLeftTwip: 0,
          quoteDepth: 0,
        },
      );

      return new docxModule.Document({
        creator: OPEN_LYRIC_EDITOR_INFO.name,
        lastModifiedBy: OPEN_LYRIC_EDITOR_INFO.name,
        title,
        subject: 'Markdown preview export',
        keywords: 'markdown,docx,open-lyric',
        numbering: {
          config: [
            {
              reference: DOCX_ORDERED_LIST_REFERENCE,
              levels: createOrderedListLevels(docxModule),
            },
          ],
        },
        sections: [
          {
            properties: {
              page: {
                margin: {
                  top: 900,
                  right: 900,
                  bottom: 900,
                  left: 900,
                },
              },
            },
            children: documentChildren.length
              ? documentChildren
              : [new docxModule.Paragraph('')],
          },
        ],
      });
    },

    async downloadMarkdownPreviewAsDocx(this: any) {
      if (this.isMarkdownPreviewActionPending) {
        return;
      }

      try {
        this.clearMarkdownPreviewProgressResetTimer();
        this.setMarkdownPreviewActionPending(true);
        await this.announceMarkdownPreviewProgress('Preparing preview', 1);

        const surface = this.createMarkdownPreviewPrintSurface();
        const previewRoot =
          surface?.querySelector('[data-ol-ref="preview"]') ||
          surface?.firstElementChild;

        if (!(previewRoot instanceof HTMLElement)) {
          this.updateMarkdownPreviewProgress({
            label: 'Markdown preview is empty',
            currentStep: 0,
            state: 'error',
          });
          this.scheduleMarkdownPreviewProgressReset(1800);
          setStatus('Markdown preview is empty');
          return;
        }

        setStatus('Building Markdown preview DOCX...');
        await this.announceMarkdownPreviewProgress('Collecting content', 2);
        await this.waitForNextFrame();
        await this.announceMarkdownPreviewProgress('Translating markdown', 3);
        const docxModule = await loadDocxModule();
        await this.announceMarkdownPreviewProgress('Building document', 4);
        const documentFile = this.buildMarkdownPreviewDocxDocument(
          previewRoot,
          docxModule,
        );
        await this.announceMarkdownPreviewProgress('Packing DOCX', 5);
        const blob = await docxModule.Packer.toBlob(documentFile);

        this.updateMarkdownPreviewProgress({
          label: 'Starting download',
          currentStep: 6,
          state: 'complete',
        });
        this.downloadBlob(blob, this.getMarkdownPreviewDocxFileName());
        this.scheduleMarkdownPreviewProgressReset(1400);
        setStatus('Markdown preview DOCX downloaded');
      } catch (error) {
        console.error('Failed to render Markdown preview as DOCX.', error);
        this.updateMarkdownPreviewProgress({
          label: 'Conversion failed',
          currentStep: 0,
          state: 'error',
        });
        this.scheduleMarkdownPreviewProgressReset(2200);
        setStatus('Failed to download Markdown preview DOCX');
      } finally {
        this.setMarkdownPreviewActionPending(false);
      }
    },
  });
}

export { applyPreviewControllerDocxExportMethods };
