/**
 * Lazy raster helpers shared by the preview components' image getters.
 *
 * `html-to-image` is imported on first use only, so a read-only text/HTML
 * embed never pays for the raster dependency (the redesign's "previews stay
 * small" goal). Rasterization needs a laid-out node, so callers must be
 * mounted before invoking these.
 */

import type * as HtmlToImageNamespace from 'html-to-image';

type HtmlToImageModule = typeof HtmlToImageNamespace;

let htmlToImagePromise: Promise<HtmlToImageModule> | null = null;

function loadHtmlToImage(): Promise<HtmlToImageModule> {
  if (!htmlToImagePromise) {
    htmlToImagePromise = import('html-to-image');
  }
  return htmlToImagePromise;
}

export async function rasterizeNodeToBlob(node: HTMLElement): Promise<Blob> {
  if (!node.isConnected) {
    throw new Error(
      'Rasterization requires a mounted node; mount() the component first.',
    );
  }

  const htmlToImage = await loadHtmlToImage();
  const blob = await htmlToImage.toBlob(node, {
    pixelRatio: 2,
    cacheBust: true,
  });
  if (!blob) {
    throw new Error('Failed to rasterize the Open Lyric preview node.');
  }
  return blob;
}

export interface RasterizeToPngOptions {
  /** Fill behind transparent pixels (e.g. the preview surface colour). */
  backgroundColor?: string;
  /** Target CSS width/height; defaults to the node's laid-out size. */
  width?: number;
  height?: number;
  /** Device-pixel multiplier for the raster (defaults to 2). */
  pixelRatio?: number;
}

export async function rasterizeNodeToDataUrl(
  node: HTMLElement,
  options: RasterizeToPngOptions = {},
): Promise<string> {
  if (!node.isConnected) {
    throw new Error(
      'Rasterization requires a mounted node; mount() the component first.',
    );
  }

  const htmlToImage = await loadHtmlToImage();
  const dataUrl = await htmlToImage.toPng(node, {
    pixelRatio: options.pixelRatio ?? 2,
    cacheBust: true,
    ...(options.backgroundColor
      ? { backgroundColor: options.backgroundColor }
      : {}),
    ...(options.width ? { width: options.width } : {}),
    ...(options.height ? { height: options.height } : {}),
  });
  if (!dataUrl) {
    throw new Error('Failed to rasterize the Open Lyric preview node.');
  }
  return dataUrl;
}
